local config = {
  ui_story_5081_50810100_1_dialog_content = "(In the blowing wind and scorching sand, my remaining companions and I make a desperate attempt to escape...)",
  ui_story_5081_50810100_2_dialog_content = "(Behind us surges a sea of Eclipsites...)",
  ui_story_5081_50810100_3_dialog_content = "(And ahead of us lies an enormous castle, a symbol of both hope and despair...)",
  ui_story_5081_50810100_4_dialog_content = "(But now it seems like a distant mirage, an ethereal bubble never meant to be touched.)",
  ui_story_5081_50810100_5_dialog_content = "Is this really the end?",
  ui_story_5081_50810100_6_dialog_content = "Drat... Looks like I won't be making it home this time! Urgh!",
  ui_story_5081_50810100_7_dialog_content = "Chirp! Sork, no!",
  ui_story_5081_50810100_8_dialog_content = "I'm going with you! We're partners to the bitter end, chirp...",
  ui_story_5081_50810100_9_dialog_content = "Sork! Bekk!",
  ui_story_5081_50810100_10_dialog_content = "Now's not the time to grieve fallen comrades...",
  ui_story_5081_50810100_11_dialog_content = "I hate to admit it, but right now... you're our last hope for survival!",
  ui_story_5081_50810100_12_dialog_content = "Don't stop! Keep going no matter what!",
  ui_story_5081_50810100_13_dialog_content = "Odi!",
  ui_story_5081_50810100_14_dialog_content = "I-I'll carry on your will! I swear to make it to the castle and find her...",
  ui_story_5081_50810100_15_dialog_content = "No wait, I just said...",
  ui_story_5081_50810100_16_dialog_content = "<color=#e8d9bb>Boom!</color>",
  ui_story_5081_50810100_17_dialog_content = "It's over...",
  ui_story_5081_50810100_18_dialog_content = "Sorry everyone, but I... wasn't able to...",
  ui_story_5081_50810100_19_dialog_content = "...",
  ui_story_5081_50810100_20_dialog_content = "<color=#e8d9bb>Beep, beep!</color>",
  ui_story_5081_50810100_21_dialog_content = "We lost again!",
  ui_story_5081_50810100_22_dialog_content = "I guess we really can't beat this without \"B,\" much less hit that high ranking.",
  ui_story_5081_50810100_23_dialog_content = "But \"B\" made her stance perfectly clear already...",
  ui_story_5081_50810100_24_dialog_content = "You... don't like playing games, do you?",
  ui_story_5081_50810100_25_dialog_content = "I'm sorry... I never should've bothered you!",
  ui_story_5081_50810100_26_dialog_content = "\"B\" can't stand me. Is there really no other way...?",
  ui_story_5081_50810100_27_dialog_content = "<color=#e8d9bb>It all started a few days ago when an urgent request from the Illumina Federation appeared.</color>",
  ui_story_5081_50810100_28_dialog_content = "I really didn't want to come to Illumina during a time like this.",
  ui_story_5081_50810100_29_dialog_content = "Everyone's so busy... It feels like a huge storm is brewing.",
  ui_story_5081_50810100_30_dialog_content = "!",
  ui_story_5081_50810100_31_dialog_content = "Huh? Isn't that Intelligence Officer Yingel?",
  ui_story_5081_50810100_32_dialog_content = "...",
  ui_story_5081_50810100_33_dialog_content = "Sh-She completely ignored me!",
  ui_story_5081_50810100_34_dialog_content = "She looked really stressed out, though... maybe she's in the middle of another secret mission.",
  ui_story_5081_50810100_35_dialog_content = "You showed up right on time, PlayerName.",
  ui_story_5081_50810100_36_dialog_content = "Oh, I just arrived, actually.",
  ui_story_5081_50810100_37_dialog_content = "Let's dispense with the small talk. I'm sure you know that I didn't ask you here at a time like this for a friendly catch-up.",
  ui_story_5081_50810100_38_dialog_content = "The Committee is in the middle of a restructuring. Naturally, this has put a sizeable strain on all of our research labs...",
  ui_story_5081_50810100_39_dialog_content = "To say every project is a total mess right now would be an understatement.",
  ui_story_5081_50810100_40_dialog_content = "So... you need my help?",
  ui_story_5081_50810100_41_dialog_content = "While you may not be able to assist with the projects themselves...",
  ui_story_5081_50810100_42_dialog_content = "I do have a task that's perfectly suited to your skills.",
  ui_story_5081_50810100_43_dialog_content = "What's the task?",
  ui_story_5081_50810100_44_dialog_content = "I'd like for you to investigate the whereabouts of Tech Officer Gronru. She suddenly disappeared from her post a few days ago and hasn't been heard from ever since.",
  ui_story_5081_50810100_45_dialog_content = "Gronru? She's gone missing?!",
  ui_story_5081_50810100_46_dialog_content = "That's right. Our sources indicate that she has already left Illumina, but her current whereabouts are unknown.",
  ui_story_5081_50810100_47_dialog_content = "We're in the middle of turbulent times here. If word of this gets out...",
  ui_story_5081_50810100_48_dialog_content = "\"Did she defect from Illumina? Could she be working with the enemy? Or maybe she's been a spy for the Wraiths all along?\"",
  ui_story_5081_50810100_49_dialog_content = "... Any of these rumors could spread like wildfire.",
  ui_story_5081_50810100_50_dialog_content = "That's a little much!",
  ui_story_5081_50810100_51_dialog_content = "(Either way, I should try reaching out to Gronru on her terminal...)",
  ui_story_5081_50810100_52_dialog_content = "I'm afraid it's the truth. Given the current circumstances, avoiding this kind of public speculation is our top priority.",
  ui_story_5081_50810100_53_dialog_content = "A number of our own people have already been assigned to handle this matter via official channels.",
  ui_story_5081_50810100_54_dialog_content = "In fact, I hear the Illumina Federation is prepared to mobilize its entire mainland intelligence network to hunt her down.",
  ui_story_5081_50810100_55_dialog_content = "Yikes.",
  ui_story_5081_50810100_56_dialog_content = "So... What will they do to Gronru once they find her? They're not gonna punish her, are they?",
  ui_story_5081_50810100_57_dialog_content = "Who knows? It's out of my jurisdiction.",
  ui_story_5081_50810100_58_dialog_content = "Out of precaution, or maybe out of fear of causing an even bigger spectacle, the Committee asked me if I had any other solutions.",
  ui_story_5081_50810100_59_dialog_content = "That's when I decided to reach out to you with this mission.",
  ui_story_5081_50810100_60_dialog_content = "We need you to find our AWOL colleague and bring her back before official action is taken.",
  ui_story_5081_50810100_61_dialog_content = "I understand, but I have to ask...",
  ui_story_5081_50810100_62_dialog_content = "Could it be that Gronru left because of how much work there is to do in Illumina right now?",
  ui_story_5081_50810100_63_dialog_content = "Maybe the stress just got to her, so she needed to step away from her work for a while?",
  ui_story_5081_50810100_64_dialog_content = "Who's to say she won't show up in Illumina just as soon as I leave?",
  ui_story_5081_50810100_65_dialog_content = "Unfortunately, that's unlikely.",
  ui_story_5081_50810100_66_dialog_content = "The average person could never understand Gronru when it comes to stress.",
  ui_story_5081_50810100_67_dialog_content = "That girl has always had a weak sense of morality, so something like this would never make her feel stressed.",
  ui_story_5081_50810100_68_dialog_content = "In fact, that's precisely the reason why we put her in charge of Illumina's most important development projects.",
  ui_story_5081_50810100_69_dialog_content = "You're right. Gronru is a genius... but she still needs a respite from work once in a while.",
  ui_story_5081_50810100_70_dialog_content = "In any case, we're counting on you. You don't want Gronru to fall into the Committee's wrinkly, old hands, do you?",
  ui_story_5081_50810100_71_dialog_content = "You don't have to put it like that. I'm willing to help either way!",
  ui_story_5081_50810100_72_dialog_content = "It's just that Gronru has a ton of hobbies, which means she could be almost anywhere in the world.",
  ui_story_5081_50810100_73_dialog_content = "She could be feeding the pigeons in Lumopolis during the day and then watching a play in Twin Pavilions Bay by night.",
  ui_story_5081_50810100_74_dialog_content = "Traveling to all those places isn't cheap, especially for me...",
  ui_story_5081_50810100_75_dialog_content = "Don't worry about the costs. I'll have a word with the Committee and make sure you're properly compensated.",
  ui_story_5081_50810100_76_dialog_content = "After all, finding the Tech Officer sooner rather than later will minimize the damage to Illumina. I'm sure they'll understand.",
  ui_story_5081_50810100_77_dialog_content = "I appreciate it! Oh, there's one more thing...",
  ui_story_5081_50810100_78_dialog_content = "I ran into Intelligence Officer Yingel just now, and she seemed really preoccupied. She didn't even say hi to me or anything.",
  ui_story_5081_50810100_79_dialog_content = "Is she okay?",
  ui_story_5081_50810100_80_dialog_content = "Yingel... With everything that has happened lately, her position has been affected even more than others.",
  ui_story_5081_50810100_81_dialog_content = "She's probably throwing herself into her work to take her mind off things.",
  ui_story_5081_50810100_82_dialog_content = "... Are you sure you guys aren't just forcing her to work overtime?",
  ui_story_5081_50810100_83_dialog_content = "On the contrary, everyone here wishes she would stop pushing herself so hard.",
  ui_story_5081_50810100_84_dialog_content = "No matter how you look at it, she's an important and talented member of the Illumina Federation. Excessive overtime is just as unacceptable as leaving one's post without permission.",
  ui_story_5081_50810100_85_dialog_content = "If you say so... I guess everyone in Illumina has it pretty rough right now.",
  ui_story_5081_50810100_86_dialog_content = "Just leave finding Gronru to me.",
  ui_story_5081_50810100_87_dialog_content = "We've been friends for a long time now, so I have a few ideas about where she could be.",
  ui_story_5081_50810100_88_dialog_content = "I'll keep you updated!",
  ui_story_5081_50810100_89_dialog_content = "(Let's list off the places where Gronru might be—)",
  ui_story_5081_50810100_90_dialog_content = "(The most likely place is Umbraton, the entertainment capital of Astra!)",
  ui_story_5081_50810100_91_dialog_content = "Cutting-edge techniques to awe the entire world! The masterful work of the Sweet Dreams Theater's newest director will be unveiled tonight!",
  ui_story_5081_50810100_92_dialog_content = "Stage-shattering performances! A sumptuous feast for the senses! The annual gathering of legendary musicians begins today!",
  ui_story_5081_50810100_93_dialog_content = "... Just look at these crowds!",
  ui_story_5081_50810100_94_dialog_content = "Every single venue is packed to capacity with visitors. Finding Gronru in this mess will be like finding a needle in a haystack...",
  ui_story_5081_50810100_95_dialog_content = "There's no response on the terminal either... Looks like this game of hide-and-seek isn't ending anytime soon.",
  ui_story_5081_50810100_96_dialog_content = "What should I do... Huh? Is that—",
  ui_story_5081_50810100_97_dialog_content = "...",
  ui_story_5081_50810100_98_dialog_content = "What's the Rediesel Wrench doing here?",
  ui_story_5081_50810100_99_dialog_content = "And why are they sneaking around like that? They're not here to cause trouble, are they?",
  ui_story_5081_50810100_100_dialog_content = "If they pick a fight with the local gangs right now, things will only get harder for me.",
  ui_story_5081_50810100_101_dialog_content = "I should go warn them.",
  ui_story_5081_50810201_1_dialog_content = "Hurry! Let's catch up!",
  ui_story_5081_50810201_2_dialog_content = "Heheh, target locked!",
  ui_story_5081_50810201_3_dialog_content = "Ahem—",
  ui_story_5081_50810201_4_dialog_content = "?",
  ui_story_5081_50810201_5_dialog_content = "Excuse me, but what exactly do you two think you're doing?",
  ui_story_5081_50810201_6_dialog_content = "Tsk, so you're here too, PlayerName...",
  ui_story_5081_50810201_7_dialog_content = "Don't tell me you're competing against us!",
  ui_story_5081_50810201_8_dialog_content = "Well, if it isn't the boss! Maybe we can strike up a deal?",
  ui_story_5081_50810201_9_dialog_content = "With your illustrious name, maybe we can secure priority for ourselves.",
  ui_story_5081_50810201_10_dialog_content = "Sorry, but I have no idea what you are talking about.",
  ui_story_5081_50810201_11_dialog_content = "Were you guys tailing someone just now?",
  ui_story_5081_50810201_12_dialog_content = "Oh no, we were just doing a slight background check on our opponents.",
  ui_story_5081_50810201_13_dialog_content = "To put it simply, we came to assess the combat strength of our enemies and identify any possible advantages they may have...",
  ui_story_5081_50810201_14_dialog_content = "After all, it's limited. Only those with skills can swipe it from others.",
  ui_story_5081_50810201_15_dialog_content = "S-Swipe something?",
  ui_story_5081_50810201_16_dialog_content = "Of course! Just look at all these people!",
  ui_story_5081_50810201_17_dialog_content = "No way! Absolutely not! I won't let you—",
  ui_story_5081_50810201_18_dialog_content = "Why can't we—",
  ui_story_5081_50810201_19_dialog_content = "Steal from Umbraton!",
  ui_story_5081_50810201_20_dialog_content = "Buy that game!",
  ui_story_5081_50810201_21_dialog_content = "Huh?",
  ui_story_5081_50810201_22_dialog_content = "So let me get this straight...",
  ui_story_5081_50810201_23_dialog_content = "A newly excavated fantasy game is about to be restored soon, and now it's on pre-sale in Umbraton.",
  ui_story_5081_50810201_24_dialog_content = "But they only have limited copies, and they're only letting gamers buy it if they pass their test.",
  ui_story_5081_50810201_25_dialog_content = "So you came here all the way from the Rediesel Desert just to pass this test and secure a copy of the game.",
  ui_story_5081_50810201_26_dialog_content = "And now you're stalking other like-minded gamers to get a better understanding of the test...",
  ui_story_5081_50810201_27_dialog_content = "You guys are really going out of your way just to buy a video game, haha...",
  ui_story_5081_50810201_28_dialog_content = "Ah... When did you develop such a crude view of the Rediesel Wrench, boss?",
  ui_story_5081_50810201_29_dialog_content = "I figured after years of friendship and fighting foes, we could have had a much better understanding of one another.",
  ui_story_5081_50810201_30_dialog_content = "Uh... Sorry?",
  ui_story_5081_50810201_31_dialog_content = "I guess you really don't understand the Rediesel Wrench... or the value of a fantasy game like this!",
  ui_story_5081_50810201_32_dialog_content = "... Is that really the point here?",
  ui_story_5081_50810201_33_dialog_content = "For Aurorians to unearth a video game from the ruins and restore it to working order...",
  ui_story_5081_50810201_34_dialog_content = "Do you have any idea how much work goes into that?",
  ui_story_5081_50810201_35_dialog_content = "H-How much?",
  ui_story_5081_50810201_36_dialog_content = "Repairing game machines is the easiest part of the process!",
  ui_story_5081_50810201_37_dialog_content = "Understanding the original coding and contents of a game, then supplementing any damaged or missing parts—that is unbelievably difficult!",
  ui_story_5081_50810201_38_dialog_content = "And don't get me started on the challenges of translating a game's ancient language into Aurorian!",
  ui_story_5081_50810201_39_dialog_content = "This type of work is one of the greatest undertakings of our time!",
  ui_story_5081_50810201_40_dialog_content = "I-I think I get it now... I guess putting out a game isn't as simple as I thought...",
  ui_story_5081_50810201_41_dialog_content = "Exactly. What's more, Illumina's technology and expertise are usually required for large-scale excavation and restoration work like this.",
  ui_story_5081_50810201_42_dialog_content = "That's what makes it all the more shocking that a game like this is being sold first in Umbraton!",
  ui_story_5081_50810201_43_dialog_content = "It's also why we have to get our hands on a copy of the special edition. Even if they double the price of the game, or even triple it, we'll pay whatever it costs!",
  ui_story_5081_50810201_44_dialog_content = "Sounds like it'll be really expensive then... You're okay with this, Jomu?",
  ui_story_5081_50810201_45_dialog_content = "Of course! The more expensive it is now, the more valuable it will be in the future!",
  ui_story_5081_50810201_46_dialog_content = "If I had to choose a favorite type of game, it's the one that makes people shell out their money hand over fist.",
  ui_story_5081_50810201_47_dialog_content = "So you're willing to buy this fantasy game even <color=#FFB400>at a premium</color>... I almost can't believe it, Jomu.",
  ui_story_5081_50810201_48_dialog_content = "You guys scraped together junk and other parts to rebuild a Colossus, but somehow you're willing to pay good money for a video game.",
  ui_story_5081_50810201_49_dialog_content = "You just don't understand, PlayerName.",
  ui_story_5081_50810201_50_dialog_content = "I already told you how much time and effort it takes to discover, unearth, restore, and release games like this...",
  ui_story_5081_50810201_51_dialog_content = "Do you think this kind of work can be done by any half-baked studio with minimal resources?",
  ui_story_5081_50810201_52_dialog_content = "I guess not.",
  ui_story_5081_50810201_53_dialog_content = "Tell me, what do you think is the most important aspect of a video game?",
  ui_story_5081_50810201_54_dialog_content = "Its... playability?",
  ui_story_5081_50810201_55_dialog_content = "Wrong! It's the gamers!",
  ui_story_5081_50810201_56_dialog_content = "If you do something despicable, like forcing professionals to develop your games or stealing limited-edition versions...",
  ui_story_5081_50810201_57_dialog_content = "You'll be ostracized by the entire gaming community!",
  ui_story_5081_50810201_58_dialog_content = "No matter how wonderful the game you have, no one will be around to share in its joy.",
  ui_story_5081_50810201_59_dialog_content = "It's the most tragic outcome imaginable for any gamer! Don't you understand?",
  ui_story_5081_50810201_60_dialog_content = "That's right! Even a game like Tetrablox is more fun when two people join in!",
  ui_story_5081_50810201_61_dialog_content = "What's more, there are plenty of notable people within the gaming community—people you definitely don't want to offend.",
  ui_story_5081_50810201_62_dialog_content = "Especially since they might be in the market for lots of new gaming peripherals... Heheheh.",
  ui_story_5081_50810201_63_dialog_content = "Gamers, huh...",
  ui_story_5081_50810201_64_dialog_content = "I'm pretty sure there are plenty of those in the Rediesel Wrench, right?",
  ui_story_5081_50810201_65_dialog_content = "You guys must be out of games to play if you're willing to come all the way to Umbraton for them...",
  ui_story_5081_50810201_66_dialog_content = "Hey! Let's get something straight here: we're perfectly capable of digging up game machines and cartridges all by ourselves!",
  ui_story_5081_50810201_67_dialog_content = "But those clumsy idiots have no idea how to take proper care of things, so our stuff gets damaged all the time!",
  ui_story_5081_50810201_68_dialog_content = "You think I can fix this sort of mess all by myself? Nope, absolutely not...",
  ui_story_5081_50810201_69_dialog_content = "If I could take a few Illuminan scientists back with me, I bet I could make a game that would take the whole world by storm!",
  ui_story_5081_50810201_70_dialog_content = "Hang on, I think I might know just the Illuminan scientist for the job...",
  ui_story_5081_50810201_71_dialog_content = "Ah! I got caught up talking to you guys and almost forgot!",
  ui_story_5081_50810201_72_dialog_content = "(I wonder if Gronru's disappearance has anything to do with this fantasy game's pre-sale?)",
  ui_story_5081_50810201_73_dialog_content = "(The timing couldn't be more perfect...)",
  ui_story_5081_50810201_74_dialog_content = "(Starting my search with this game isn't a bad choice at all. Now then...)",
  ui_story_5081_50810201_75_dialog_content = "Hmm... Could you tell me where they're selling this game?",
  ui_story_5081_50810201_76_dialog_content = "But of course, my dear friend! I'll even give you a twenty percent discount for that information—",
  ui_story_5081_50810201_77_dialog_content = "Hidden Fangs.",
  ui_story_5081_50810201_78_dialog_content = "Well...",
  ui_story_5081_50810201_79_dialog_content = "Yes, that's right—Hidden Fangs!",
  ui_story_5081_50810201_80_dialog_content = "A mecca for every gamer in Astra! The one and only supreme arcade of Umbraton!",
  ui_story_5081_50810201_81_dialog_content = "I'm still not paying you for that info, you know...",
  ui_story_5081_50810201_82_dialog_content = "It's also a gathering place for high-level gamers. Most, if not all, of Astra's video game records have been set there.",
  ui_story_5081_50810201_83_dialog_content = "... Sounds like a real hall of fame, I guess.",
  ui_story_5081_50810201_84_dialog_content = "(I wonder if any of Gronru's high scores are recorded there?)",
  ui_story_5081_50810201_85_dialog_content = "(You're definitely on the right track now, Caelestite! Keep it up!)",
  ui_story_5081_50810201_86_dialog_content = "Unfortunately, you probably won't be able to secure a copy even if you add your name to the list right now.",
  ui_story_5081_50810201_87_dialog_content = "Huh? But I thought this was a pre-sale! Was I supposed to reserve a spot on the waiting list?",
  ui_story_5081_50810201_88_dialog_content = "It has nothing to do with the waiting list...",
  ui_story_5081_50810201_89_dialog_content = "Video game cartridges are extremely valuable, so the arcade is conducting a strict review of any potential buyers.",
  ui_story_5081_50810201_90_dialog_content = "It's all to prevent scalpers and other malicious actors from getting involved so that real gamers have an opportunity to enjoy the game.",
  ui_story_5081_50810201_91_dialog_content = "No wonder Jomu looks so nervous about it.",
  ui_story_5081_50810201_92_dialog_content = "Haha, very funny, boss. Mark my words: I'll earn the right to purchase a copy from \"B\" fair and square!",
  ui_story_5081_50810201_93_dialog_content = "\"B\"?",
  ui_story_5081_50810201_94_dialog_content = "That's right. The most crucial step in securing a copy of this game is to play against \"B.\"",
  ui_story_5081_50810201_95_dialog_content = "As the owner of Hidden Fangs, she's also one of Astra's greatest gamers...",
  ui_story_5081_50810201_96_dialog_content = "That's how \"B\" tests you to see if your love of video games is real or not.",
  ui_story_5081_50810201_97_dialog_content = "I don't think a newbie like you could handle it.",
  ui_story_5081_50810201_98_dialog_content = "Wh-What are you talking about? I've played tons of games too!",
  ui_story_5081_50810201_99_dialog_content = "Heheheh. I'll just have to tell you a little more about \"B,\" so you can wallow in despair...",
  ui_story_5081_50810301_1_dialog_content = "<color=#e8d9bb>A body made entirely of games.</color>",
  ui_story_5081_50810301_2_dialog_content = "<color=#e8d9bb>With a computer for a heart, and data for blood.</color>",
  ui_story_5081_50810301_3_dialog_content = "<color=#e8d9bb>She has played thousands of games without losing a single time.</color>",
  ui_story_5081_50810301_4_dialog_content = "<color=#e8d9bb>Her existence is a mystery to both Aurorians and Eclipsites alike.</color>",
  ui_story_5081_50810301_5_dialog_content = "<color=#e8d9bb>On most days, she lurks in the darkest corners of the arcade, muttering to herself about being useless.</color>",
  ui_story_5081_50810301_6_dialog_content = "<color=#e8d9bb>She has but one desire in life: an infinite amount of games to play!</color>",
  ui_story_5081_50810301_7_dialog_content = "...",
  ui_story_5081_50810301_8_dialog_content = "Stop already! The story just keeps getting crazier and crazier!",
  ui_story_5081_50810301_9_dialog_content = "So to put it simply... \"B\" is a gamer who has played countless games and hasn't lost a single time?",
  ui_story_5081_50810301_10_dialog_content = "To be more precise—",
  ui_story_5081_50810301_11_dialog_content = "She has some of the fastest clearance records and highest scores in all of Astra, and she's also the most famous Tetrablox player of all time.",
  ui_story_5081_50810301_12_dialog_content = "She keeps setting records in Tetrablox's infinity mode as well. Some even say she's made it to the very last level of the game...",
  ui_story_5081_50810301_13_dialog_content = "Can a game like that really have a final level?",
  ui_story_5081_50810301_14_dialog_content = "From what I've heard, the game freezes once you clear a certain number of levels...",
  ui_story_5081_50810301_15_dialog_content = "Either way, it's not something an ordinary Aurorian could ever do.",
  ui_story_5081_50810301_16_dialog_content = "Is she some sort of gaming monster spawned from the deepest depths of the ancient ruins? She very well could be!",
  ui_story_5081_50810301_17_dialog_content = "Settle down, I get it already. She's really good at video games...",
  ui_story_5081_50810301_18_dialog_content = "In any case, lots of challengers have gone to Hidden Fangs looking for \"B,\" only to limp away in defeat!",
  ui_story_5081_50810301_19_dialog_content = "Actually, I just want to ask around for some information. I'm not interested in challenging \"B\" at all!",
  ui_story_5081_50810301_20_dialog_content = "This person doesn't sound very approachable either...",
  ui_story_5081_50810301_21_dialog_content = "Not to worry, boss! I'd be more than happy to inquire on your behalf, and for a five percent discount—",
  ui_story_5081_50810301_22_dialog_content = "You'll be fine, so just go there and see for yourself! There are all kinds of gamers there, you'll see.",
  ui_story_5081_50810301_23_dialog_content = "Thanks guys. Lead the way!",
  ui_story_5081_50810301_24_dialog_content = "<color=#e8d9bb>Creak—</color>",
  ui_story_5081_50810301_25_dialog_content = "... Is this really the place?",
  ui_story_5081_50810301_26_dialog_content = "It's a lot more comfortable than I thought it would be!",
  ui_story_5081_50810301_27_dialog_content = "I'm even getting a sense of nostalgia, as if I'm about to sit down and play one of my favorite games.",
  ui_story_5081_50810301_28_dialog_content = "It's just an arcade, you know. What did you think it would be like",
  ui_story_5081_50810301_29_dialog_content = "Are you seriously asking me that after that crazy description you gave me?",
  ui_story_5081_50810301_30_dialog_content = "At the very least, I thought it would be full of Umbraton gangsters or something...",
  ui_story_5081_50810301_31_dialog_content = "I bet the owner of this cozy little store must be someone who really loves life!",
  ui_story_5081_50810301_32_dialog_content = "...",
  ui_story_5081_50810301_33_dialog_content = "Huh?",
  ui_story_5081_50810301_34_dialog_content = "!",
  ui_story_5081_50810301_35_dialog_content = "I don't know about life, but she definitely loves games...",
  ui_story_5081_50810301_36_dialog_content = "Hmm? What's the matter, PlayerName? You look like something's bothering you.",
  ui_story_5081_50810301_37_dialog_content = "For some reason... it feels like someone's watching me.",
  ui_story_5081_50810301_38_dialog_content = "You're just imagining things. The lighting here isn't very bright, after all.",
  ui_story_5081_50810301_39_dialog_content = "Besides, everyone's too busy playing games to notice you...",
  ui_story_5081_50810301_40_dialog_content = "You're right, I guess I'm just worrying over nothing.",
  ui_story_5081_50810301_41_dialog_content = "So where's the arcade's owner? For something as important as a game's pre-sale, there's hardly anything advertising it.",
  ui_story_5081_50810301_42_dialog_content = "Could she be testing someone to see if they're worthy of buying the game?",
  ui_story_5081_50810301_43_dialog_content = "Not to worry, boss. The owner is a very passionate person, and I'm sure she'll answer you if you call out to her—loudly, of course.",
  ui_story_5081_50810301_44_dialog_content = "Okay, uh... Excuse me! Can I please speak to \"B\"?",
  ui_story_5081_50810301_45_dialog_content = "?",
  ui_story_5081_50810301_46_dialog_content = "Is that a new challenger?",
  ui_story_5081_50810301_47_dialog_content = "Wait, I think I've seen that outfit before... Isn't he a famous person?",
  ui_story_5081_50810301_48_dialog_content = "Yeah! This will be awesome!",
  ui_story_5081_50810301_49_dialog_content = "You set me up, Jomu!",
  ui_story_5081_50810301_50_dialog_content = "Sorry boss, but since you didn't pay for my information, I had to think of another way to collect my compensation. Best of luck!",
  ui_story_5081_50810301_51_dialog_content = "...",
  ui_story_5081_50810301_52_dialog_content = "You've got a lot of guts, calling for \"B\" like that...",
  ui_story_5081_50810301_53_dialog_content = "Welcome to Hidden Fangs! Hope you're ready for a challenge!",
  ui_story_5081_50810301_54_dialog_content = "... Huh?",
  ui_story_5081_50810301_55_dialog_content = "Oh? Well, if it isn't PlayerName!",
  ui_story_5081_50810301_56_dialog_content = "It's PlayerName, chirp!",
  ui_story_5081_50810301_57_dialog_content = "Sork? Bekk?",
  ui_story_5081_50810301_58_dialog_content = "What are you two doing here?",
  ui_story_5081_50810301_59_dialog_content = "That's my line, pal! What are you... Hey! Jomu's here too!",
  ui_story_5081_50810301_60_dialog_content = "Quit hiding behind PlayerName, you bum! Gimme back the money you owe me, or else...",
  ui_story_5081_50810301_61_dialog_content = "Save me, boss!",
  ui_story_5081_50810301_62_dialog_content = "Not a chance, especially after you set me up like that...",
  ui_story_5081_50810301_63_dialog_content = "Well... Unfortunately, I only brought enough money to buy this game today, you see.",
  ui_story_5081_50810301_64_dialog_content = "As an employee of this store, surely you wouldn't want me to leave empty-handed, right?",
  ui_story_5081_50810301_65_dialog_content = "Sork works here?",
  ui_story_5081_50810301_66_dialog_content = "He just welcomed you like an employee, didn't he?",
  ui_story_5081_50810301_67_dialog_content = "Well... It's a long story.",
  ui_story_5081_50810301_68_dialog_content = "Originally, Bekk and I got hired to buy some new games for a client here in Umbraton.",
  ui_story_5081_50810301_69_dialog_content = "But in the end, we got ripped off by some shady salesman and ended up with a bunch of junk cartridges.",
  ui_story_5081_50810301_70_dialog_content = "With no money and business to complete, we decided to spend the night in this arcade...",
  ui_story_5081_50810301_71_dialog_content = "So the owner was kind enough to offer you guys jobs while you're here?",
  ui_story_5081_50810301_72_dialog_content = "Kind? Heh, more like curious.",
  ui_story_5081_50810301_73_dialog_content = "The owner wanted to see how well Bekk and I worked together, so she invited us to play a game.",
  ui_story_5081_50810301_74_dialog_content = "If we won, she'd cover all our losses. If we lost, we'd have to work for her.",
  ui_story_5081_50810301_75_dialog_content = "Drat! We were so close to winning too...",
  ui_story_5081_50810301_76_dialog_content = "We lost by a hair, chirp!",
  ui_story_5081_50810301_77_dialog_content = "You two \"lost by a hair\"? Ha, don't make me laugh!",
  ui_story_5081_50810301_78_dialog_content = "If this is \"B\" we're talking about here, she probably stomped you guys into the ground!",
  ui_story_5081_50810301_79_dialog_content = "What? How did you know she used her feet? That's how she was able to use two controllers at the same time...",
  ui_story_5081_50810301_80_dialog_content = "She beat us using her hands and feet at the same time!",
  ui_story_5081_50810301_81_dialog_content = "S-She did?",
  ui_story_5081_50810301_82_dialog_content = "Anyway, one thing led to another, and now we're both working here...",
  ui_story_5081_50810301_83_dialog_content = "When it's not busy, we even get to play tabletop games with our customers.",
  ui_story_5081_50810301_84_dialog_content = "People can completely immerse themselves in strategy games here—that's not something you can find in most places...",
  ui_story_5081_50810301_85_dialog_content = "Even though negotiation games are way better, chirp!",
  ui_story_5081_50810301_86_dialog_content = "So you two get caught up in the games here too, huh?",
  ui_story_5081_50810301_87_dialog_content = "There really is something special about this place... but why haven't I seen the store's owner anywhere?",
  ui_story_5081_50810301_88_dialog_content = "\"B\" has rare demi-human ancestry, just like us. It's not easy for her to come out during the day.",
  ui_story_5081_50810301_89_dialog_content = "She dealt with a lot of trouble in the past because of her ancestry too. So, please...",
  ui_story_5081_50810301_90_dialog_content = "Just try to understand.",
  ui_story_5081_50810301_91_dialog_content = "I-I totally get it!",
  ui_story_5081_50810301_92_dialog_content = "I just have something to ask her, that's all. Would you like to pass a message on to her?",
  ui_story_5081_50810301_93_dialog_content = "Of course, PlayerName.",
  ui_story_5081_50810301_94_dialog_content = "Just let me finish this game... I mean, dealing with these customers, and I'll get right on it.",
  ui_story_5081_50810301_95_dialog_content = "Sure.",
  ui_story_5081_50810301_96_dialog_content = "Huh? I wonder where Odi and Jomu went...",
  ui_story_5081_50810301_97_dialog_content = "Are you kidding me? I came up with tons of new strategies just so I could earn my copy of the game!",
  ui_story_5081_50810301_98_dialog_content = "See, I even modified my own controller... Take a look if you want!",
  ui_story_5081_50810301_99_dialog_content = "That's so cool!",
  ui_story_5081_50810301_100_dialog_content = "Pardon me friend, but would you like to play a few rounds of Rediesel Hold 'em with me? I think we might be quite evenly matched!",
  ui_story_5081_50810301_101_dialog_content = "But where I come from, the loser usually covers the winner's expenses for the rest of the day. Interested?",
  ui_story_5081_50810301_102_dialog_content = "Sure, I'm game!",
  ui_story_5081_50810301_103_dialog_content = "Everyone seems to be having a lot of fun.",
  ui_story_5081_50810301_104_dialog_content = "I should play something too, so I don't stick out so much...",
  ui_story_5081_50810301_105_dialog_content = "Hmm, what to choose...",
  ui_story_5081_50810301_106_dialog_content = "This one looks pretty fun. Aurora All-Star Racing—I should be pretty good at driving games, right?",
  ui_story_5081_50810301_107_dialog_content = "Guess I'd better put in a token and find out!",
  ui_story_5081_50810301_108_dialog_content = "Wow, look at all these vehicle choices! I can even pick weapons too!",
  ui_story_5081_50810301_109_dialog_content = "Alright, I think I've got the hang of it now. Let's go!",
  ui_story_5081_50810301_110_dialog_content = "<color=#e8d9bb>Though the game's graphics are fairly simple, players still feel as though they've been transported into a new world.</color>",
  ui_story_5081_50810301_111_dialog_content = "<color=#e8d9bb>The detailed images, coupled with their exaggerated presentation and special sound effects, create an immersive experience.</color>",
  ui_story_5081_50810301_112_dialog_content = "Is this how I'm supposed to take the corners? I totally understand it now!",
  ui_story_5081_50810301_113_dialog_content = "I gather Lumina whenever I drift around a corner, so am I supposed to fire it at the Eclipsites? Guess I'd better give it a shot!",
  ui_story_5081_50810301_114_dialog_content = "Wait... This Eclipsite's a little too strong, isn't it?",
  ui_story_5081_50810301_115_dialog_content = "Uh-oh... Why can't I see the Lumina trails?",
  ui_story_5081_50810301_116_dialog_content = "Oh, man... This game doesn't include the Caelestites' strongest ability! It's totally unfair!",
  ui_story_5081_50810301_117_dialog_content = "Actually, this is the <color=#FFB400>fairest</color> aspect of the game.",
  ui_story_5081_50810301_118_dialog_content = "Huh?",
  ui_story_5081_50810301_119_dialog_content = "<color=#e8d9bb>Player 2 has entered the game!</color>",
  ui_story_5081_50810301_120_dialog_content = "Another player... has joined my game?",
  ui_story_5081_50810301_121_dialog_content = "... D-Don't look at me!",
  ui_story_5081_50810301_122_dialog_content = "Just keep your eyes on your screen, or else you'll crash.",
  ui_story_5081_50810301_123_dialog_content = "Sorry!",
  ui_story_5081_50810301_124_dialog_content = "It's my first time playing, so I apologize if I get in your way...",
  ui_story_5081_50810301_125_dialog_content = "Don't worry, I'll show you how to play.",
  ui_story_5081_50810301_126_dialog_content = "You have lots of potential. Focus your attention, and it shouldn't be a problem.",
  ui_story_5081_50810301_127_dialog_content = "O-Okay then...",
  ui_story_5081_50810301_128_dialog_content = "<color=#e8d9bb>Warning! Warning! A large wave of Eclipsites is inbound!</color>",
  ui_story_5081_50810301_129_dialog_content = "Get ready, we're doing this together.",
  ui_story_5081_50810301_130_dialog_content = "Roger!",
  ui_story_5081_50810302_1_dialog_content = "?",
  ui_story_5081_50810302_2_dialog_content = "I-I'm still alive?",
  ui_story_5081_50810302_3_dialog_content = "I can't believe we made it out of that horde of Eclipsites!",
  ui_story_5081_50810302_4_dialog_content = "Does this mean I'm close to clearing the stage?",
  ui_story_5081_50810302_5_dialog_content = "... Did you have fun?",
  ui_story_5081_50810302_6_dialog_content = "Fun? Of course it was fun! I just don't think I could've played that long without your help.",
  ui_story_5081_50810302_7_dialog_content = "That's not necessarily true. You'll have to rely on yourself for the next part... but I'm sure you'll be fine.",
  ui_story_5081_50810302_8_dialog_content = "Huh?",
  ui_story_5081_50810302_9_dialog_content = "<color=#e8d9bb>Player 2 has left the game!</color>",
  ui_story_5081_50810302_10_dialog_content = "You're leaving just like that?",
  ui_story_5081_50810302_11_dialog_content = "... I told you not to look at me! Eyes on the screen!",
  ui_story_5081_50810302_12_dialog_content = "Right! I can't afford to lose focus now...",
  ui_story_5081_50810302_13_dialog_content = "You already helped me get past the hardest part, so now it's up to me to finish the rest!",
  ui_story_5081_50810302_14_dialog_content = "I can handle whatever this game throws at me! Sharp turns, Eclipsites, you name it!",
  ui_story_5081_50810302_15_dialog_content = "Oh? I didn't realize you were playing too, PlayerName... and you seem pretty pumped up!",
  ui_story_5081_50810302_16_dialog_content = "Wait, this is the Tempest Gorge stage, isn't it? I know you're totally unaware of how hard this race is, but try not to lose right away...",
  ui_story_5081_50810302_17_dialog_content = "Wow! Come take a look, Odi. He already cleared the five consecutive hairpin turns in Tempest Gorge!",
  ui_story_5081_50810302_18_dialog_content = "Impossible! Even I couldn't get past that wave of Eclipsites... I refuse to accept this!",
  ui_story_5081_50810302_19_dialog_content = "Wow! Check this out, everyone!",
  ui_story_5081_50810302_20_dialog_content = "Huh? Why is everyone suddenly gathering around me?",
  ui_story_5081_50810302_21_dialog_content = "<color=#e8d9bb>Under everyone's eager gaze, clearing the stage suddenly becomes even more difficult.</color>",
  ui_story_5081_50810302_22_dialog_content = "<color=#e8d9bb>But in the end, the arcade explodes into cheers as the race comes to an exciting and successful conclusion.</color>",
  ui_story_5081_50810302_23_dialog_content = "Wow!",
  ui_story_5081_50810302_24_dialog_content = "A newbie cleared Tempest Gorge on his first try? How's that even possible?",
  ui_story_5081_50810302_25_dialog_content = "I bet this guy is actually a pro gamer!",
  ui_story_5081_50810302_26_dialog_content = "Where'd you even come from, new guy? Are you here to show off your skills?",
  ui_story_5081_50810302_27_dialog_content = "I-Is this stage really that hard?",
  ui_story_5081_50810302_28_dialog_content = "Don't get the wrong idea, everybody! I'm nothing special, and this is my first time here. Besides, I had lots of help from another player...",
  ui_story_5081_50810302_29_dialog_content = "When I was fighting my way through those hairpin turns, she was sitting right next to... Huh?",
  ui_story_5081_50810302_30_dialog_content = "Really? Because I don't see anyone.",
  ui_story_5081_50810302_31_dialog_content = "She was here just a second ago!",
  ui_story_5081_50810302_32_dialog_content = "A tiny Aurorian... who seemed not totally awake...",
  ui_story_5081_50810302_33_dialog_content = "I think she might be a bat demi-human, and her hair looked kind of like the lights in the arcade...",
  ui_story_5081_50810302_34_dialog_content = "Heh... Do you have any idea who you just described?",
  ui_story_5081_50810302_35_dialog_content = "Chirp! A tiny bat demi-human!",
  ui_story_5081_50810302_36_dialog_content = "That sounds a lot like Batia, the owner of the arcade!",
  ui_story_5081_50810401_1_dialog_content = "...",
  ui_story_5081_50810401_2_dialog_content = "It feels like I'm waiting to be interviewed...",
  ui_story_5081_50810401_3_dialog_content = "Don't look so flustered. If \"B\" was willing to play with you, it definitely means you caught her attention.",
  ui_story_5081_50810401_4_dialog_content = "I could call her over if you'd like to.",
  ui_story_5081_50810401_5_dialog_content = "We're not gonna get any more pre-orders today if we don't get any new challengers.",
  ui_story_5081_50810401_6_dialog_content = "That means we'll have to keep working here, chirp!",
  ui_story_5081_50810401_7_dialog_content = "I understand. Let's do this!",
  ui_story_5081_50810401_8_dialog_content = "<color=#e8d9bb>Creak—</color>",
  ui_story_5081_50810401_9_dialog_content = "... Oh.",
  ui_story_5081_50810401_10_dialog_content = "... Hmm.",
  ui_story_5081_50810401_11_dialog_content = "... Phew.",
  ui_story_5081_50810401_12_dialog_content = "Excuse me...",
  ui_story_5081_50810401_13_dialog_content = "Uh... Yep!",
  ui_story_5081_50810401_14_dialog_content = "... Was something wrong with my greeting just now?",
  ui_story_5081_50810401_15_dialog_content = "<size=30>(... Or maybe I'm supposed to communicate with her in arcade terms?)</size>",
  ui_story_5081_50810401_16_dialog_content = "No... Hmm...",
  ui_story_5081_50810401_17_dialog_content = "!",
  ui_story_5081_50810401_18_dialog_content = "D-Did you... need something from me?",
  ui_story_5081_50810401_19_dialog_content = "It's nothing special, really.",
  ui_story_5081_50810401_20_dialog_content = "I'm a Caelestite, and my name is the same as the one I used in-game.",
  ui_story_5081_50810401_21_dialog_content = "I came here looking for someone. Could you tell me if you've seen...",
  ui_story_5081_50810401_22_dialog_content = "I-I haven't! I definitely don't take in kids when they run away from home and let them play video games here!",
  ui_story_5081_50810401_23_dialog_content = "Y-Y-You've got the wrong place... I swear!",
  ui_story_5081_50810401_24_dialog_content = "Huh? Do I really look like a disgruntled parent to you?",
  ui_story_5081_50810401_25_dialog_content = "Oh, I guess not...",
  ui_story_5081_50810401_26_dialog_content = "That's because I'm not! I came looking for someone who looks really young but is actually a lot older than she seems! She's one of Illumina's greatest scientists!",
  ui_story_5081_50810401_27_dialog_content = "She abandoned all of her important lab duties and disappeared without any explanation recently.",
  ui_story_5081_50810401_28_dialog_content = "She really enjoys video games, so I thought this would be a good place to start searching...",
  ui_story_5081_50810401_29_dialog_content = "Her name is Gronru. Do you know anything about her?",
  ui_story_5081_50810401_30_dialog_content = "I don't.",
  ui_story_5081_50810401_31_dialog_content = "I-Is that so...",
  ui_story_5081_50810401_32_dialog_content = "(That was such a quick response... a little too quick, if you ask me.)",
  ui_story_5081_50810401_33_dialog_content = "(Is she trying to avoid causing a scene? Makes sense, considering this is supposed to be a paradise for all gamers... Wait, gamers...)",
  ui_story_5081_50810401_34_dialog_content = "Sorry! I think I asked the wrong question.",
  ui_story_5081_50810401_35_dialog_content = "People here probably go by their player names, don't they?",
  ui_story_5081_50810401_36_dialog_content = "Now what was Gronru's player name again? That's right! She goes by Gronkenstein Ruu! Have you heard of her?",
  ui_story_5081_50810401_37_dialog_content = "Gronken what?",
  ui_story_5081_50810401_38_dialog_content = "Gronkenstein Ruu!",
  ui_story_5081_50810401_39_dialog_content = "Grompen... Stein?",
  ui_story_5081_50810401_40_dialog_content = "No, Gronkenst—ouch! I bit my tongue!",
  ui_story_5081_50810401_41_dialog_content = "Anyway... I don't know any famous scientists.",
  ui_story_5081_50810401_42_dialog_content = "I've had lots of players come to my store lately... It's kind of impossible... to remember all of their names.",
  ui_story_5081_50810401_43_dialog_content = "Sorry, but... I don't think I can be of much help.",
  ui_story_5081_50810401_44_dialog_content = "Hang on, let me think. There might be another clue I can use here...",
  ui_story_5081_50810401_45_dialog_content = "You... don't like playing games, do you?",
  ui_story_5081_50810401_46_dialog_content = "Huh?",
  ui_story_5081_50810401_47_dialog_content = "You didn't come here to play games... You came to look for someone.",
  ui_story_5081_50810401_48_dialog_content = "When we teamed up in Aurora All-Star Racing and cleared Tempest Gorge...",
  ui_story_5081_50810401_49_dialog_content = "It was no different than right now. You didn't want to stand out, so you felt like you had to play, right?",
  ui_story_5081_50810401_50_dialog_content = "I'm sorry... I never should've bothered you!",
  ui_story_5081_50810401_51_dialog_content = "H-Hey! Don't say that.",
  ui_story_5081_50810401_52_dialog_content = "I was having tons of fun when we were playing together just now! It was super exciting!",
  ui_story_5081_50810401_53_dialog_content = "But once I calm down, I remember just how important my mission is, and I have to get back to the task at hand. That's why...",
  ui_story_5081_50810401_54_dialog_content = "...",
  ui_story_5081_50810401_55_dialog_content = "Did I scare her off because I was too focused on my mission?",
  ui_story_5081_50810401_56_dialog_content = "You should try talking to her again. Moping around won't do you any good.",
  ui_story_5081_50810401_57_dialog_content = "You should know how to get closer to her by now. After all, her hobby is pretty obvious.",
  ui_story_5081_50810401_58_dialog_content = "You mean video games...",
  ui_story_5081_50810401_59_dialog_content = "And even if it's not to approach her again, you just mentioned Gronru's player name, didn't you?",
  ui_story_5081_50810401_60_dialog_content = "Why don't you play a couple of games and see if her name shows up on the leaderboards?",
  ui_story_5081_50810401_61_dialog_content = "That should tell you if she's been here recently or not.",
  ui_story_5081_50810401_62_dialog_content = "I see! That's a great idea, Odi!",
  ui_story_5081_50810401_63_dialog_content = "Besides, since you cleared Tempest Gorge just now, I want to see if your skills are the real deal.",
  ui_story_5081_50810401_64_dialog_content = "I'll cover the tokens, so come play a few matches with me!",
  ui_story_5081_50810401_65_dialog_content = "Sure, I'll be right there.",
  ui_story_5081_50810401_66_dialog_content = "What's that? Odi's paying today? Well, count me in!",
  ui_story_5081_50810401_67_dialog_content = "I can't miss out on this either...",
  ui_story_5081_50810401_68_dialog_content = "Count us in too! Chirp!",
  ui_story_5081_50810401_69_dialog_content = "Guys...",
  ui_story_5081_50810401_70_dialog_content = "Come on everybody, let's look for signs of Gronru in the high scores!",
  ui_story_5081_50810402_1_dialog_content = "<color=#e8d9bb>GAME OVER!</color>",
  ui_story_5081_50810402_2_dialog_content = "We lost again? Urgh, to heck with it! Put more tokens in!",
  ui_story_5081_50810402_3_dialog_content = "Actually, we're all out of tokens...",
  ui_story_5081_50810402_4_dialog_content = "What? Jomu, go get us some more!",
  ui_story_5081_50810402_5_dialog_content = "Eh? Me? You must be joking... Sork, why don't you go buy a few more?",
  ui_story_5081_50810402_6_dialog_content = "Me? But I'm an employee here!",
  ui_story_5081_50810402_7_dialog_content = "It'd be a little awkward, wouldn't it? Besides, you were playing like trash just now, Jomu! At least make yourself useful somehow!",
  ui_story_5081_50810402_8_dialog_content = "Jomu plays like trash, chirp!",
  ui_story_5081_50810402_9_dialog_content = "I-I'm just not that good at this type of game! You don't blame me, do you? Boss?",
  ui_story_5081_50810402_10_dialog_content = "Nah, especially since I'm not that great at it either. Odi had to carry me the whole time.",
  ui_story_5081_50810402_11_dialog_content = "The real problem is that even with our combined skills, I don't think we'll ever see Gronru's high score...",
  ui_story_5081_50810402_12_dialog_content = "Because we can't even make it onto the leaderboards!",
  ui_story_5081_50810402_13_dialog_content = "I knew it... We need Batia's help to pull this off, but...",
  ui_story_5081_50810402_14_dialog_content = "...",
  ui_story_5081_50810402_15_dialog_content = "It looks like she wants nothing to do with me now!",
  ui_story_5081_50810402_16_dialog_content = "Heheh, I wouldn't be so sure, PlayerName.",
  ui_story_5081_50810402_17_dialog_content = "After working in the store for a few days, I can tell you that she rarely approaches customers to play with them.",
  ui_story_5081_50810402_18_dialog_content = "She was willing to partner up with you the moment you walked into this place, which means she must really like you.",
  ui_story_5081_50810402_19_dialog_content = "Chirp! PlayerName has hidden potential!",
  ui_story_5081_50810402_20_dialog_content = "But she looked so disappointed in me earlier...",
  ui_story_5081_50810402_21_dialog_content = "I'm pretty sure it's just this pre-sale event taking its toll on her nerves.",
  ui_story_5081_50810402_22_dialog_content = "She's been assessing players non-stop and accepting challenges the entire time, on top of her usual duties as the arcade's owner...",
  ui_story_5081_50810402_23_dialog_content = "She's probably just too tired to pay close attention to your words right now.",
  ui_story_5081_50810402_24_dialog_content = "It's not your fault, PlayerName!",
  ui_story_5081_50810402_25_dialog_content = "... You really think so?",
  ui_story_5081_50810402_26_dialog_content = "You can be really slow sometimes, you know that? Haven't you figured it out yet?",
  ui_story_5081_50810402_27_dialog_content = "Figured what out?",
  ui_story_5081_50810402_28_dialog_content = "\"B\" is a shut-in! She's socially anxious!",
  ui_story_5081_50810402_29_dialog_content = "Taking over a store like this is already hard enough for someone like her.",
  ui_story_5081_50810402_30_dialog_content = "But to give gamers like us a place to come together and play...",
  ui_story_5081_50810402_31_dialog_content = "She's been doing her best to overcome her social anxiety and keep this place running!",
  ui_story_5081_50810402_32_dialog_content = "Knowing that, it makes sense that she can't give you an answer when you ask her about stuff outside of video games, right?",
  ui_story_5081_50810402_33_dialog_content = "I see...",
  ui_story_5081_50810402_34_dialog_content = "(But still, I really don't want to give up such a good lead...)",
  ui_story_5081_50810402_35_dialog_content = "(I can't shake the feeling that Gronru is somehow connected to this place!)",
  ui_story_5081_50810402_36_dialog_content = "Boss? Boss!",
  ui_story_5081_50810402_37_dialog_content = "Huh? What now, Jomu? Don't tell me you're gonna try to scam me again...",
  ui_story_5081_50810402_38_dialog_content = "Scam you? Your words cut deep, boss! I happen to care about your interests more than anyone else!",
  ui_story_5081_50810402_39_dialog_content = "And I've come up with an idea just for you.",
  ui_story_5081_50810402_40_dialog_content = "And that would be?",
  ui_story_5081_50810402_41_dialog_content = "Why don't you try clearing a B-Stage?",
  ui_story_5081_50810402_42_dialog_content = "A what now?",
  ui_story_5081_50810402_43_dialog_content = "Since the store owner can't possibly address every single challenger, she has set up a number of unique stages on some of the arcade's game machines.",
  ui_story_5081_50810402_44_dialog_content = "If you can clear them...",
  ui_story_5081_50810402_45_dialog_content = "She might even allow you to copy the original version of this game!",
  ui_story_5081_50810402_46_dialog_content = "After that, we can make a bunch of copies and sell them as official versions!",
  ui_story_5081_50810402_47_dialog_content = "We can also hide some of the content behind a paywall and make even more per copy, heehee...",
  ui_story_5081_50810402_48_dialog_content = "We'll make a killing in no time!",
  ui_story_5081_50810402_49_dialog_content = "... And we'll become the most hated people in the gaming community! I thought you said offending them was a bad idea?",
  ui_story_5081_50810402_50_dialog_content = "That's why we'll do everything under your name, boss! No one would ever suspect the legendary Caelestite, after all...",
  ui_story_5081_50810402_51_dialog_content = "Alright, that's enough of your harebrained schemes. I've already met so many gamers here today...",
  ui_story_5081_50810402_52_dialog_content = "They're all very nice, and they genuinely love video games. I refuse to rip them off!",
  ui_story_5081_50810402_53_dialog_content = "Come on boss! Don't be like that!",
  ui_story_5081_50810402_54_dialog_content = "Hey, is that...",
  ui_story_5081_50810402_55_dialog_content = "Huh? What's going on over there?",
  ui_story_5081_50810402_56_dialog_content = "Looks like a new challenger to me. I'll go welcome them!",
  ui_story_5081_50810402_57_dialog_content = "Sure, just try not to sneak up on them with your creepy \"welcome\" again...",
  ui_story_5081_50810402_58_dialog_content = "That might be the reason you're not making that many sales!",
  ui_story_5081_50810402_59_dialog_content = "Another upstart who doesn't know their place, huh? C'mon PlayerName, let's go.",
  ui_story_5081_50810402_60_dialog_content = "... Go where?",
  ui_story_5081_50810402_61_dialog_content = "Go see what the hubbub is about! Now that I think of it, you still haven't seen Batia's skills in action, have you?",
  ui_story_5081_50810402_62_dialog_content = "I guess not...",
  ui_story_5081_50810402_63_dialog_content = "(This is probably a good opportunity to get to know Batia better too.)",
  ui_story_5081_50810402_64_dialog_content = "I'll do my best to watch and learn!",
  ui_story_5081_50810501_1_dialog_content = "Excuse me, but is the owner of Hidden Fangs in?",
  ui_story_5081_50810501_2_dialog_content = "Oh? Is this the latest challenger?",
  ui_story_5081_50810501_3_dialog_content = "I've seen her before! She's a hired gun from Umbraton and a self-proclaimed antique connoisseur!",
  ui_story_5081_50810501_4_dialog_content = "Did someone important hire her to come here?",
  ui_story_5081_50810501_5_dialog_content = "Not at all. I came here of my own accord.",
  ui_story_5081_50810501_6_dialog_content = "I was told that I could buy a limited-edition copy of a game by challenging the arcade's owner, a person by the name of \"B.\"",
  ui_story_5081_50810501_7_dialog_content = "Hey, Allura! Fancy seeing you here!",
  ui_story_5081_50810501_8_dialog_content = "PlayerName? ... What an unexpected surprise.",
  ui_story_5081_50810501_9_dialog_content = "Have you already secured a copy of the game?",
  ui_story_5081_50810501_10_dialog_content = "Well...",
  ui_story_5081_50810501_11_dialog_content = "It seems not. A pity, since buying it from you would probably save me time. Still...",
  ui_story_5081_50810501_12_dialog_content = "I'm interested to see just how skilled this \"B\" person truly is.",
  ui_story_5081_50810501_13_dialog_content = "Another challenger... Welcome.",
  ui_story_5081_50810501_14_dialog_content = "Oh? So this little girl is \"B\"?",
  ui_story_5081_50810501_15_dialog_content = "Not bad, it only took you forty-six seconds to appear before me... Do you accept my challenge?",
  ui_story_5081_50810501_16_dialog_content = "I'd like to ask you something first... Why do you want to buy this game?",
  ui_story_5081_50810501_17_dialog_content = "To add it to my precious collection, of course.",
  ui_story_5081_50810501_18_dialog_content = "A fully restored fantasy game is the perfect fusion of technology and entertainment, as well as a rare and priceless antique.",
  ui_story_5081_50810501_19_dialog_content = "The data stored within its cartridge is just as valuable as the words written in the ancient tomes I've collected.",
  ui_story_5081_50810501_20_dialog_content = "If I fail to acquire this fantasy game, the value of my entire collection will drop by one point five percent.",
  ui_story_5081_50810501_21_dialog_content = "A data collector, huh...",
  ui_story_5081_50810501_22_dialog_content = "Fine. I accept your challenge.",
  ui_story_5081_50810501_23_dialog_content = "What? Really?",
  ui_story_5081_50810501_24_dialog_content = "But it doesn't look like Allura came to play video games either...",
  ui_story_5081_50810501_25_dialog_content = "Data collecting is also a very important part of being a gamer, PlayerName.",
  ui_story_5081_50810501_26_dialog_content = "Aside from a cartridge's design and artwork, the ancient video game data stored within is also extremely valuable.",
  ui_story_5081_50810501_27_dialog_content = "The act of collecting itself is an important aspect of gaming too...",
  ui_story_5081_50810501_28_dialog_content = "This arcade isn't just a home for gamers—it's also a home for avid collectors!",
  ui_story_5081_50810501_29_dialog_content = "You can choose whichever game you like, as long as it can be played here.",
  ui_story_5081_50810501_30_dialog_content = "That's exactly the kind of confidence I'd expect from a legendary gamer.",
  ui_story_5081_50810501_31_dialog_content = "This is my choice, Emperor of Light, Version 98.",
  ui_story_5081_50810501_32_dialog_content = "... How unexpected.",
  ui_story_5081_50810501_33_dialog_content = "Maybe it was wrong of me to assume, but given your appearance... I was sure you'd better choose a shooting game before anything else.",
  ui_story_5081_50810501_34_dialog_content = "You weren't wrong to assume, but I came prepared to play this game, and I have no intention of changing my decision.",
  ui_story_5081_50810501_35_dialog_content = "What I admire about this game is that it's both classic and accessible.",
  ui_story_5081_50810501_36_dialog_content = "... What the heck are they talking about?",
  ui_story_5081_50810501_37_dialog_content = "The challenger wants to play a classic fighting game, but \"B\" thinks she should choose a shooting game instead.",
  ui_story_5081_50810501_38_dialog_content = "So what does \"Version 98\" mean? Don't tell me... Could it mean the Year 1998 of the Morning Calendar?",
  ui_story_5081_50810501_39_dialog_content = "Precisely. 1998 was a good year for entertainment in Umbraton, and lots of fantastic games came out during that time...",
  ui_story_5081_50810501_40_dialog_content = "Ah! They're about to start!",
  ui_story_5081_50810501_41_dialog_content = "It doesn't look like you need to warm up or even check your move list...",
  ui_story_5081_50810501_42_dialog_content = "In that case... let's begin.",
  ui_story_5081_50810501_43_dialog_content = "Wow! The first challenger of the day has taken her seat—",
  ui_story_5081_50810501_44_dialog_content = "And \"B,\" the undisputed champion, has logged into her own account!",
  ui_story_5081_50810501_45_dialog_content = "There it is! Her legendary player name!",
  ui_story_5081_50810501_46_dialog_content = "It's her, no doubt about it! We finally get to see her in action!",
  ui_story_5081_50810501_47_dialog_content = "L-Live commentating? Are you trying to go back to your old job or something, Odi?",
  ui_story_5081_50810501_48_dialog_content = "No epic battle is complete without some choice refreshments! Umbraton snacks and drinks for sale right here!",
  ui_story_5081_50810501_49_dialog_content = "This guy, on the other hand, has never stopped working... Wait, aren't these snacks from the Rediesel Desert?",
  ui_story_5081_50810501_50_dialog_content = "Quiet, boss! I mean... Naturally, I made a few adjustments to suit local tastes.",
  ui_story_5081_50810501_51_dialog_content = "Anyway, if you keep wasting time over here, you'll miss the end of the first round!",
  ui_story_5081_50810501_52_dialog_content = "Wh-What?",
  ui_story_5081_50810501_53_dialog_content = "<color=#e8d9bb>K.O.! Perfect!</color>",
  ui_story_5081_50810501_54_dialog_content = "Amazing!",
  ui_story_5081_50810501_55_dialog_content = "\"B\" took the initiative from the very start of the round! With a jump and a dash, she threw her opponent and didn't let up on her till the end!",
  ui_story_5081_50810501_56_dialog_content = "With no room to counter, the challenger had no choice but to admit defeat!",
  ui_story_5081_50810501_57_dialog_content = "Going all out in the first round? I was planning to counter after one and a half seconds...",
  ui_story_5081_50810501_58_dialog_content = "But she managed to take the win in under a single second.",
  ui_story_5081_50810501_59_dialog_content = "Even so, I think I understand your playstyle a little better now. Let's keep going.",
  ui_story_5081_50810501_60_dialog_content = "Humph, you really think you have it figured out?",
  ui_story_5081_50810501_61_dialog_content = "I'll give you ten chances to beat me. If you do, I'll let you buy a copy of the game.",
  ui_story_5081_50810501_62_dialog_content = "Then you're severely underestimating me. Let's go!",
  ui_story_5081_50810501_63_dialog_content = "(When Batia immerses herself in a game, it's like she becomes a completely different person.)",
  ui_story_5081_50810501_64_dialog_content = "(Confident, serious, unrestrained, but most importantly... it looks like she's having fun.)",
  ui_story_5081_50810501_65_dialog_content = "(Could this be the real her?)",
  ui_story_5081_50810501_66_dialog_content = "(I should keep watching, both the game and this legendary player...)",
  ui_story_5081_50810502_1_dialog_content = "<color=#e8d9bb>K.O.!</color>",
  ui_story_5081_50810502_2_dialog_content = "It's over! After ten whole attempts, the challenger was unable to score even a single win!",
  ui_story_5081_50810502_3_dialog_content = "In spite of this, she kept up the pressure and managed to push \"B\" into a corner a few times...",
  ui_story_5081_50810502_4_dialog_content = "There's no denying it! Today's challenger deserves recognition, if not simply for her incredible fighting spirit!",
  ui_story_5081_50810502_5_dialog_content = "<size=30>You're getting a little too fired up, Odi...</size>",
  ui_story_5081_50810502_6_dialog_content = "...",
  ui_story_5081_50810502_7_dialog_content = "Unbelievable... I had a feeling I would lose, but I didn't expect to lose so spectacularly.",
  ui_story_5081_50810502_8_dialog_content = "As expected of the legendary \"B.\" I admit defeat.",
  ui_story_5081_50810502_9_dialog_content = "You're welcome to challenge me at another game, if you'd like to...",
  ui_story_5081_50810502_10_dialog_content = "No need. I'm completely aware of the skill gap between us now. It would be pointless to continue.",
  ui_story_5081_50810502_11_dialog_content = "I understand... but your skills are still worthy of respect.",
  ui_story_5081_50810502_12_dialog_content = "I can tell you did a lot of last-minute practicing, but you did a great job of pressing your advantages and covering up your weaknesses.",
  ui_story_5081_50810502_13_dialog_content = "Your knowledge of your characters' move sets, damage ratios, skill effects, and even their frames is extremely high.",
  ui_story_5081_50810502_14_dialog_content = "With more time and training, maybe...",
  ui_story_5081_50810502_15_dialog_content = "You could best me in a single match... as long as I'm not using my best characters, of course.",
  ui_story_5081_50810502_16_dialog_content = "\"B\" actually acknowledged her challenger?",
  ui_story_5081_50810502_17_dialog_content = "Even though she would be limiting herself, I can't believe \"B\" admitted that someone could actually beat her!",
  ui_story_5081_50810502_18_dialog_content = "Oh? I don't know if I have that kind of potential... but your analysis is entirely correct.",
  ui_story_5081_50810502_19_dialog_content = "To add that fantasy game to my collection, I did perform some last-minute practice on this classic game.",
  ui_story_5081_50810502_20_dialog_content = "The reason I didn't choose another game is because I'm not as experienced at them. However...",
  ui_story_5081_50810502_21_dialog_content = "Uh... D-Do you still want to challenge me at something?",
  ui_story_5081_50810502_22_dialog_content = "No. This is my business card.",
  ui_story_5081_50810502_23_dialog_content = "I, uh, don't know what I'm supposed to do with this.",
  ui_story_5081_50810502_24_dialog_content = "Just hold onto it, if you would.",
  ui_story_5081_50810502_25_dialog_content = "After all, I definitely want to experience the <color=#FFB400>joy of gaming</color> now.",
  ui_story_5081_50810502_26_dialog_content = "Especially when it comes to extremely detailed games like this... Ah, I can't let myself lose as badly as today ever again!",
  ui_story_5081_50810502_27_dialog_content = "Did you... have fun playing just now?",
  ui_story_5081_50810502_28_dialog_content = "Yes, I did. At first, I just wanted to add some games to my antique collection.",
  ui_story_5081_50810502_29_dialog_content = "But now, I finally realize how much more enjoyable it is to actually play them... and this game is so much more complex than I imagined!",
  ui_story_5081_50810502_30_dialog_content = "If there are more games like this out there, I'll greatly appreciate it if you introduce them to me!",
  ui_story_5081_50810502_31_dialog_content = "Got it... Actually, I think we might have a few extra cartridges lying around... You're welcome to try them out too...",
  ui_story_5081_50810502_32_dialog_content = "And... if I discover any similar games, I'll let you know right away.",
  ui_story_5081_50810502_33_dialog_content = "A-Also, you passed. You are now worthy of purchasing a copy of this fantasy game!",
  ui_story_5081_50810502_34_dialog_content = "Huh? But I thought I lost?",
  ui_story_5081_50810502_35_dialog_content = "Winning or losing doesn't determine a player's worthiness... What matters most is that they enjoy playing games!",
  ui_story_5081_50810502_36_dialog_content = "I see...",
  ui_story_5081_50810502_37_dialog_content = "Looks like it's time to get back to work. I can help you pay for it over here, miss.",
  ui_story_5081_50810502_38_dialog_content = "Congratulations! Finally, someone earned the right to buy the game!",
  ui_story_5081_50810502_39_dialog_content = "I'm so jealous! But after seeing them go head-to-head, I know I don't stand a chance...",
  ui_story_5081_50810502_40_dialog_content = "You're all too kind.",
  ui_story_5081_50810502_41_dialog_content = "This arcade truly is a wonderful place.",
  ui_story_5081_50810502_42_dialog_content = "Alright! Amid waves of applause, the newcomer emerges from Hidden Fangs, smiling and victorious!",
  ui_story_5081_50810502_43_dialog_content = "And while there are still plenty of challengers in the arcade, they don't look so sure of themselves now!",
  ui_story_5081_50810502_44_dialog_content = "You didn't need to add that last part, Odi! Besides... I-I'm starting to think I'm not skilled enough to—",
  ui_story_5081_50810502_45_dialog_content = "Haven't you realized it yet, PlayerName? How can you still think this challenge is based solely on skill?",
  ui_story_5081_50810502_46_dialog_content = "Think, you goof! What was the reason \"B\" decided to team up with you earlier?",
  ui_story_5081_50810502_47_dialog_content = "The reason, huh...",
  ui_story_5081_50810502_48_dialog_content = "Is this how I'm supposed to take the corners? I totally understand it now!",
  ui_story_5081_50810502_49_dialog_content = "I gather Lumina whenever I drift around a corner, so am I supposed to fire it at the Eclipsites? Guess I'd better give it a shot!",
  ui_story_5081_50810502_50_dialog_content = "Back then... I was totally lost in the game.",
  ui_story_5081_50810502_51_dialog_content = "Maybe she thought I really liked games when she saw me like that, so she decided to join me.",
  ui_story_5081_50810502_52_dialog_content = "No need for the \"maybe\"! Do you really think you caught her attention with just your skills alone?",
  ui_story_5081_50810502_53_dialog_content = "Hey, no need to be so blunt!",
  ui_story_5081_50810502_54_dialog_content = "As long as you're willing to respect, understand, and enjoy games here, you'll have no trouble understanding her.",
  ui_story_5081_50810502_55_dialog_content = "You won't find a friendlier, more enthusiastic person than \"B\" if you do!",
  ui_story_5081_50810502_56_dialog_content = "There's a catch, though... She consumes a ton of mana whenever she gets fired up, and it also has a pretty long cooldown!",
  ui_story_5081_50810502_57_dialog_content = "I understand. Finding Gronru might be a similar situation too.",
  ui_story_5081_50810502_58_dialog_content = "I just need to try to understand them... and experience the video games they love so much for myself.",
  ui_story_5081_50810502_59_dialog_content = "Once I do, I'll finally be able to see things from their perspective and get closer to both of them.",
  ui_story_5081_50810502_60_dialog_content = "Maybe Gronru's just waiting for someone who understands her too.",
  ui_story_5081_50810502_61_dialog_content = "We've been waiting for you to say that, boss! And I already took the liberty of signing us both up!",
  ui_story_5081_50810502_62_dialog_content = "Now let's go challenge \"B\" and make our fortunes!",
  ui_story_5081_50810502_63_dialog_content = "Pardon me, but is this where I can challenge the person known as \"B\"?",
  ui_story_5081_50810502_64_dialog_content = "Ah! Another challenger! Let's go take a look!",
  ui_story_5081_50810502_65_dialog_content = "Wait for me, boss!",
  ui_story_5081_50810601_1_dialog_content = "What an unexpected challenger!",
  ui_story_5081_50810601_2_dialog_content = "Judging from her clothes, I think she's from Lumopolis!",
  ui_story_5081_50810601_3_dialog_content = "Is anyone going to answer me? I'm here to challenge \"B\"!",
  ui_story_5081_50810601_4_dialog_content = "Who's in charge here?",
  ui_story_5081_50810601_5_dialog_content = "Beretta?",
  ui_story_5081_50810601_6_dialog_content = "PlayerName? Are you working here by chance?",
  ui_story_5081_50810601_7_dialog_content = "If so, could you help me sign up for the challenge?",
  ui_story_5081_50810601_8_dialog_content = "No, I think you're looking for the store owner... Oh, here she comes!",
  ui_story_5081_50810601_9_dialog_content = "...",
  ui_story_5081_50810601_10_dialog_content = "Excellent!",
  ui_story_5081_50810601_11_dialog_content = "Forgive me for failing to notice you earlier. My name is Beretta, and I'm a field medic from Lumopolis.",
  ui_story_5081_50810601_12_dialog_content = "How may I address you? And how may I sign up to challenge the legendary \"B\"?",
  ui_story_5081_50810601_13_dialog_content = "You can call me Batia. Which game would you like to play for the challenge?",
  ui_story_5081_50810601_14_dialog_content = "Any game is fine, but I would prefer to play your hardest, most grueling game!",
  ui_story_5081_50810601_15_dialog_content = "To be honest, this is my first time visiting an establishment like this. With so many challengers and difficulties in sight...",
  ui_story_5081_50810601_16_dialog_content = "Even though I've never played games seriously before, this is the perfect place to test my resolve!",
  ui_story_5081_50810601_17_dialog_content = "... This is just an arcade, not a training ground... You'll only find gamers gathered here.",
  ui_story_5081_50810601_18_dialog_content = "If you want to test your resolve... I-I suggest going elsewhere.",
  ui_story_5081_50810601_19_dialog_content = "Games are a great way to test one's willpower! I hear many of Illumina's finest soldiers train this way!",
  ui_story_5081_50810601_20_dialog_content = "Unfortunately, Lumopolis lacks these kinds of training methods. When I heard that Umbraton had a place like this, I had to come and see it for myself!",
  ui_story_5081_50810601_21_dialog_content = "Now, may I please challenge this so-called \"B\" to a training match?",
  ui_story_5081_50810601_22_dialog_content = "I-I'm \"B.\"",
  ui_story_5081_50810601_23_dialog_content = "But I refuse to accept a challenge from someone who doesn't know the rules of a game...",
  ui_story_5081_50810601_24_dialog_content = "If you really want to challenge me... p-please pick a game and learn how to play it first.",
  ui_story_5081_50810601_25_dialog_content = "Very well, I'll do just that! Thank you!",
  ui_story_5081_50810601_26_dialog_content = "She's actually studying how to play!",
  ui_story_5081_50810601_27_dialog_content = "... Is this really okay? I think she's even more focused on her goal than I am!",
  ui_story_5081_50810601_28_dialog_content = "I think \"B\" just doesn't know how to deal with someone like her.",
  ui_story_5081_50810601_29_dialog_content = "Beating her opponents as soon as possible is how she usually does things.",
  ui_story_5081_50810601_30_dialog_content = "Something tells me that won't work too well on someone like Beretta...",
  ui_story_5081_50810601_31_dialog_content = "Ahh! How could this be?",
  ui_story_5081_50810601_32_dialog_content = "I was here first, wasn't I?",
  ui_story_5081_50810601_33_dialog_content = "That training maniac doesn't know the first thing about video games, does she? This is going to take forever!",
  ui_story_5081_50810601_34_dialog_content = "Maybe we should look into more dubious methods, boss...",
  ui_story_5081_50810601_35_dialog_content = "Don't worry, I'm a very quick study. They also have fighting games, which should be a natural fit for me!",
  ui_story_5081_50810601_36_dialog_content = "Looks like Beretta's going to choose the same game as Allura. I guess that's what she meant by \"classic and accessible,\" huh?",
  ui_story_5081_50810601_37_dialog_content = "The controller's all beat up. This game must be really popular.",
  ui_story_5081_50810601_38_dialog_content = "Excuse me... but is anybody even listening?",
  ui_story_5081_50810601_39_dialog_content = "You guys... can both challenge me.",
  ui_story_5081_50810601_40_dialog_content = "Hmm? What do you mean by that?",
  ui_story_5081_50810601_41_dialog_content = "The two of you can team up against me. I'll still win... so it doesn't matter.",
  ui_story_5081_50810601_42_dialog_content = "I admire your confidence, but I must decline.",
  ui_story_5081_50810601_43_dialog_content = "Losing in a two-versus-one match would be shameful, but winning against you would be no better.",
  ui_story_5081_50810601_44_dialog_content = "Even though this young man appears to be an utter weakling, the numbers would still be in our favor.",
  ui_story_5081_50810601_45_dialog_content = "I refuse to accept this—unless you team up with someone yourself!",
  ui_story_5081_50810601_46_dialog_content = "You training freak... We'll see who the real weakling is soon enough!",
  ui_story_5081_50810601_47_dialog_content = "An ally? ... I don't need one. There's no reason for me to trouble anyone, since...",
  ui_story_5081_50810601_48_dialog_content = "If you don't mind—",
  ui_story_5081_50810601_49_dialog_content = "Would it be okay if I team up with you?",
  ui_story_5081_50810601_50_dialog_content = "Huh?",
  ui_story_5081_50810601_51_dialog_content = "Haha, I'm not sure if I'm returning the favor or if it's something else...",
  ui_story_5081_50810601_52_dialog_content = "But we made a pretty good team earlier, don't you think?",
  ui_story_5081_50810601_53_dialog_content = "If it hadn't been for you, I never would've cleared such a difficult stage. So now it's my turn to be your Player 2!",
  ui_story_5081_50810601_54_dialog_content = "You...",
  ui_story_5081_50810601_55_dialog_content = "Seeing all of these serious challengers is getting me fired up too.",
  ui_story_5081_50810601_56_dialog_content = "I bet I could enjoy this game to its fullest if you let me play on your team!",
  ui_story_5081_50810601_57_dialog_content = "I-If that's how you really feel...",
  ui_story_5081_50810601_58_dialog_content = "Then let's play together!",
  ui_story_5081_50810601_59_dialog_content = "...",
  ui_story_5081_50810601_60_dialog_content = "Thanks for that, boss! You know what to do now, right?",
  ui_story_5081_50810601_61_dialog_content = "Wh-What are you talking about?",
  ui_story_5081_50810601_62_dialog_content = "With your sabotage, this two-versus-two match will turn into a three-versus-one fight!",
  ui_story_5081_50810601_63_dialog_content = "Even with this training freak on our team, we'll still have a chance of beating her! Hahahaha!",
  ui_story_5081_50810601_64_dialog_content = "I'll be sure to give you your cut afterward!",
  ui_story_5081_50810601_65_dialog_content = "... You think I'm going to <color=#FFB400>sabotage</color> the match?",
  ui_story_5081_50810601_66_dialog_content = "That does it! Time for you to feel the power of the Last Caelestite!",
  ui_story_5081_50810602_1_dialog_content = "<color=#e8d9bb>K.O.!</color>",
  ui_story_5081_50810602_2_dialog_content = "Boss, no! This isn't what we agreed on!",
  ui_story_5081_50810602_3_dialog_content = "Stop fooling around, weakling! You're going to cost us the match!",
  ui_story_5081_50810602_4_dialog_content = "That's right! And for the record, I didn't agree to anything! Now bring it on, I'm ready to keep supporting you, Batia!",
  ui_story_5081_50810602_5_dialog_content = "Then I'll let you handle this fight.",
  ui_story_5081_50810602_6_dialog_content = "Huh?",
  ui_story_5081_50810602_7_dialog_content = "Focus, the game is on!",
  ui_story_5081_50810602_8_dialog_content = "Okay! Wait, Jomu, I'm not ready yet! Don't you have any manners?",
  ui_story_5081_50810602_9_dialog_content = "Sorry, boss, but I'm just playing the game! Once the match starts, anything goes!",
  ui_story_5081_50810602_10_dialog_content = "Concentration is an important part of training, PlayerName! I'm going all out too!",
  ui_story_5081_50810602_11_dialog_content = "Th-That's a little—",
  ui_story_5081_50810602_12_dialog_content = "Don't worry, I'm still here.",
  ui_story_5081_50810602_13_dialog_content = "Just play as best as you can. We won't lose.",
  ui_story_5081_50810602_14_dialog_content = "You're right. After all, I can't lose with the legendary \"B\" on my side!",
  ui_story_5081_50810602_15_dialog_content = "Jomu's not very good, and Beretta's completely new to the game. I just need to handle them with a calm, focused hand...",
  ui_story_5081_50810602_16_dialog_content = "Oh? It looks like this doubles challenge has entered an entirely new phase!",
  ui_story_5081_50810602_17_dialog_content = "\"B\" has switched roles with the Last Caelestite and is playing support now! She must have a lot of trust in him!",
  ui_story_5081_50810602_18_dialog_content = "And on this side, Training Freak and Weakling are scrambling to get their teamwork in order!",
  ui_story_5081_50810602_19_dialog_content = "Hey, Odi! We're on the same team, remember? What kind of name is that?",
  ui_story_5081_50810602_20_dialog_content = "While Training Freak charges into her opponents head-on, Weakling continues his obnoxious provocation! Could this be a feint of some kind?",
  ui_story_5081_50810602_21_dialog_content = "Now's our chance!",
  ui_story_5081_50810602_22_dialog_content = "<color=#e8d9bb>Wham, wham—smack!</color>",
  ui_story_5081_50810602_23_dialog_content = "Ouch! The Last Caelestite is getting battered around mercilessly! That HP bar isn't looking too good, folks! How much longer can he hold on?",
  ui_story_5081_50810602_24_dialog_content = "Urgh... M-Maybe we should switch back?",
  ui_story_5081_50810602_25_dialog_content = "Don't panic. I already have her teammate completely under control.",
  ui_story_5081_50810602_26_dialog_content = "As for her, just keep an eye on her movements... both in and out of the game.",
  ui_story_5081_50810602_27_dialog_content = "The way to win should be perfectly clear.",
  ui_story_5081_50810602_28_dialog_content = "R-Really? Let's see...",
  ui_story_5081_50810602_29_dialog_content = "Take that! And that! I won't let up no matter what!",
  ui_story_5081_50810602_30_dialog_content = "<color=#e8d9bb>Tap, tap, tap, tap, bang—</color>",
  ui_story_5081_50810602_31_dialog_content = "There's my chance!",
  ui_story_5081_50810602_32_dialog_content = "Under Training Freak's brutal onslaught, the Last Caelestite finally bares his fangs and strikes back! But can he keep up the pressure?",
  ui_story_5081_50810602_33_dialog_content = "He's doing it! It looks like Training Freak has made a mistake...",
  ui_story_5081_50810602_34_dialog_content = "The attack just keeps coming! Could this be the end?",
  ui_story_5081_50810602_35_dialog_content = "<color=#e8d9bb>K.O.!</color>",
  ui_story_5081_50810602_36_dialog_content = "He's done it! The Last Caelestite wins!",
  ui_story_5081_50810602_37_dialog_content = "Watching from the sidelines and running interference, \"B\" led her teammate to victory with just guidance alone!",
  ui_story_5081_50810602_38_dialog_content = "...",
  ui_story_5081_50810602_39_dialog_content = "B-Best two out of three?",
  ui_story_5081_50810602_40_dialog_content = "I lost this time... There's nothing more to say.",
  ui_story_5081_50810602_41_dialog_content = "Despite my skills in combat, I was completely and thoroughly defeated. It appears this type of training must be approached much more seriously.",
  ui_story_5081_50810602_42_dialog_content = "Forgive me. I was arrogant for challenging you.",
  ui_story_5081_50810602_43_dialog_content = "There's a huge difference between fighting games and actual combat. The techniques involved are completely different too.",
  ui_story_5081_50810602_44_dialog_content = "Conflating the two... never ends well.",
  ui_story_5081_50810602_45_dialog_content = "Is that so? Interesting. May I ask you to explain this concept as a teacher would to her students?",
  ui_story_5081_50810602_46_dialog_content = "T-Teacher? N-No, I could never... I'm not fit to be anyone's teacher.",
  ui_story_5081_50810602_47_dialog_content = "Ah, what a pity...",
  ui_story_5081_50810602_48_dialog_content = "It's fine, I can explain it to you in Batia's place.",
  ui_story_5081_50810602_49_dialog_content = "... Huh?",
  ui_story_5081_50810602_50_dialog_content = "PlayerName? By all means! Your skills just now were also quite surprising.",
  ui_story_5081_50810602_51_dialog_content = "I was only able to see your moves thanks to Batia's advice, and I think...",
  ui_story_5081_50810602_52_dialog_content = "You were treating the game just like a real fight, weren't you?",
  ui_story_5081_50810602_53_dialog_content = "Of course I was! Whether it's reaction speed, movement tracking, or proper positioning...",
  ui_story_5081_50810602_54_dialog_content = "All of these aspects are just as important in video games as they are in live combat!",
  ui_story_5081_50810602_55_dialog_content = "You have a point, but they're not entirely the same.",
  ui_story_5081_50810602_56_dialog_content = "How so?",
  ui_story_5081_50810602_57_dialog_content = "In fighting games, very small and precise inputs can produce extremely powerful results.",
  ui_story_5081_50810602_58_dialog_content = "But you were mashing buttons and yanking on the joystick so hard just now, as though you were trying to channel your actual strength into the game.",
  ui_story_5081_50810602_59_dialog_content = "There are all sorts of characters in video games, and they can't always perform the actions you want them to do. That's why...",
  ui_story_5081_50810602_60_dialog_content = "Not only were you wasting your strength, but you were also negatively affecting your inputs, which gave me the opening I needed to fight back.",
  ui_story_5081_50810602_61_dialog_content = "... So all it took for you to defeat me was understanding this simple concept?",
  ui_story_5081_50810602_62_dialog_content = "Yeah... But again, it was only thanks to Batia's advice.",
  ui_story_5081_50810602_63_dialog_content = "I... didn't do anything. It's just common sense, that's all.",
  ui_story_5081_50810602_64_dialog_content = "I understand.",
  ui_story_5081_50810602_65_dialog_content = "That's why Illumina soldiers <color=#FFB400>adjust themselves</color> to suit the <color=#FFB400>firepower</color> of their weapons... It all makes sense now!",
  ui_story_5081_50810602_66_dialog_content = "Games can definitely be used for training... Or rather, training can be seen as a kind of game!",
  ui_story_5081_50810602_67_dialog_content = "This experience has been both surprising and enlightening!",
  ui_story_5081_50810602_68_dialog_content = "Thank you, Batia! Would it be alright if I come back to challenge you in the future?",
  ui_story_5081_50810602_69_dialog_content = "?",
  ui_story_5081_50810602_70_dialog_content = "Th-That depends... D-Did you have...",
  ui_story_5081_50810602_71_dialog_content = "Hmm?",
  ui_story_5081_50810602_72_dialog_content = "I think she wants to ask if you had fun just now, and if you enjoyed playing that game.",
  ui_story_5081_50810602_73_dialog_content = "Of course! It was such a thrilling experience! I had no idea video games could be so enjoyable!",
  ui_story_5081_50810602_74_dialog_content = "And something tells me I'll gain much more experience if I keep playing them!",
  ui_story_5081_50810602_75_dialog_content = "In this endeavor, I will never falter!",
  ui_story_5081_50810602_76_dialog_content = "Then... Please accept this.",
  ui_story_5081_50810602_77_dialog_content = "She passed! Th-This can't be! She has no idea how much that game is worth...",
  ui_story_5081_50810602_78_dialog_content = "Are you recommending this game to me? Very well then! I'll be sure to practice night and day once I obtain my copy!",
  ui_story_5081_50810602_79_dialog_content = "I look forward to our next duel!",
  ui_story_5081_50810602_80_dialog_content = "Uh... O-O-Okay!",
  ui_story_5081_50810602_81_dialog_content = "And once I master the secrets of Illumina's video game training...",
  ui_story_5081_50810602_82_dialog_content = "I may have a chance to finally redeem my loss against Yingel!",
  ui_story_5081_50810602_83_dialog_content = "Yingel?",
  ui_story_5081_50810602_84_dialog_content = "An intelligence officer in the Illumina Federation, yes.",
  ui_story_5081_50810602_85_dialog_content = "Following my defeat at her hands during the Joint Military Exercise, I often think about how best to claim victory over her.",
  ui_story_5081_50810602_86_dialog_content = "I even ran into her on my way here!",
  ui_story_5081_50810602_87_dialog_content = "But she was so busy that she failed to notice me...",
  ui_story_5081_50810602_88_dialog_content = "She's...",
  ui_story_5081_50810602_89_dialog_content = "!",
  ui_story_5081_50810602_90_dialog_content = "Huh? Isn't that Intelligence Officer Yingel?",
  ui_story_5081_50810602_91_dialog_content = "...",
  ui_story_5081_50810602_92_dialog_content = "Guess I'm not the only one who got ignored.",
  ui_story_5081_50810602_93_dialog_content = "What's the matter?",
  ui_story_5081_50810602_94_dialog_content = "Oh, nothing.",
  ui_story_5081_50810602_95_dialog_content = "(What's a high-level intelligence officer from Illumina doing in Umbraton anyway? Could she be looking for Gronru too?)",
  ui_story_5081_50810602_96_dialog_content = "Well, if you see her, let her know about my impending challenge!",
  ui_story_5081_50810602_97_dialog_content = "W-Will do.",
  ui_story_5081_50810602_98_dialog_content = "Fantasy game—my greatest cash cow yet! I did it... I'm finally worthy of it! Wow!",
  ui_story_5081_50810602_99_dialog_content = "You're still going on about that, Jomu? ... Huh? What are you doing on the floor?",
  ui_story_5081_50810602_100_dialog_content = "I did it... I passed... Blegh...",
  ui_story_5081_50810602_101_dialog_content = "Looks like he got a little motion sickness from playing too long... I knew he wasn't cut out for this type of game!",
  ui_story_5081_50810602_102_dialog_content = "If I had known he was willing to risk his life for money, I never would've brought him along.",
  ui_story_5081_50810602_103_dialog_content = "Even though he never stopped talking about making money, when I saw him play earlier...",
  ui_story_5081_50810602_104_dialog_content = "Jomu looked like he was having a lot of fun, didn't he?",
  ui_story_5081_50810602_105_dialog_content = "... I was so close to fooling \"B\" just now... What a pity...",
  ui_story_5081_50810602_106_dialog_content = "(Even a money-grubbing merchant like Jomu can get sucked into playing video games. I guess that's the power of their appeal.)",
  ui_story_5081_50810602_107_dialog_content = "My head is spinning... Water... I need water...",
  ui_story_5081_50810602_108_dialog_content = "Hang tight, I'll go get some drinks for you and Odi. After all that commentating, I'm sure she's thirsty too.",
  ui_story_5081_50810602_109_dialog_content = "Think of it as a thank-you gift for bringing me here today.",
  ui_story_5081_50810602_110_dialog_content = "I'll be right back!",
  ui_story_5081_50810701_1_dialog_content = "<color=#e8d9bb>Clunk—</color>",
  ui_story_5081_50810701_2_dialog_content = "Is it me, or do these machines really look like they come from Illumina?",
  ui_story_5081_50810701_3_dialog_content = "I wonder what Jomu and Odi want to drink?",
  ui_story_5081_50810701_4_dialog_content = "Maybe something \"classic and accessible\"?",
  ui_story_5081_50810701_5_dialog_content = "<color=#e8d9bb>Clunk—</color>",
  ui_story_5081_50810701_6_dialog_content = "...",
  ui_story_5081_50810701_7_dialog_content = "I knew someone was watching me.",
  ui_story_5081_50810701_8_dialog_content = "Who's there?",
  ui_story_5081_50810701_9_dialog_content = "Ahh! I... I'm sorry!",
  ui_story_5081_50810701_10_dialog_content = "Huh? It's you, Batia.",
  ui_story_5081_50810701_11_dialog_content = "Sorry for shouting. I thought someone was trying to steal my tokens or something.",
  ui_story_5081_50810701_12_dialog_content = "I-Is that so... U-Um...",
  ui_story_5081_50810701_13_dialog_content = "Wow! Is that... ice cream? But why aren't you eating it? It looks like it's about to melt!",
  ui_story_5081_50810701_14_dialog_content = "I-It's for you...",
  ui_story_5081_50810701_15_dialog_content = "Wait... You bought this just for me?",
  ui_story_5081_50810701_16_dialog_content = "Yeah.",
  ui_story_5081_50810701_17_dialog_content = "Then I'd better eat it quick! Thankfully, it's not completely melted yet...",
  ui_story_5081_50810701_18_dialog_content = "I'm not sure it can be called \"ice\" cream anymore though.",
  ui_story_5081_50810701_19_dialog_content = "But that's okay! We can always buy more! Besides, it's still perfectly edible. Whoa, that's cold!",
  ui_story_5081_50810701_20_dialog_content = "Really? I'm so happy that you like it.",
  ui_story_5081_50810701_21_dialog_content = "Also... I want to thank you.",
  ui_story_5081_50810701_22_dialog_content = "For teaming up with me... a-and for helping me handle that overly enthusiastic challenger.",
  ui_story_5081_50810701_23_dialog_content = "I should be the one thanking you! I never would've stood a chance without your help.",
  ui_story_5081_50810701_24_dialog_content = "And since you were kind enough to bring me ice cream, why don't I treat you to a drink? Juice or coffee?",
  ui_story_5081_50810701_25_dialog_content = "Um... Th-The tomato juice, please...",
  ui_story_5081_50810701_26_dialog_content = "Coming right up!",
  ui_story_5081_50810701_27_dialog_content = "<color=#e8d9bb>Clunk—</color>",
  ui_story_5081_50810701_28_dialog_content = "Here you go! So you like this kind of drink, huh?",
  ui_story_5081_50810701_29_dialog_content = "Uh-huh... I don't go out much during the day, so I rely on stuff like this for nutrition... It works pretty well too.",
  ui_story_5081_50810701_30_dialog_content = "Uh, sorry for asking... but does it have to do with being part bat?",
  ui_story_5081_50810701_31_dialog_content = "It does... which is why going outside is such a problem for me.",
  ui_story_5081_50810701_32_dialog_content = "Interacting with others... isn't very easy for me either.",
  ui_story_5081_50810701_33_dialog_content = "I'm an Aurorian like anyone else... but not entirely.",
  ui_story_5081_50810701_34_dialog_content = "There's a lot of stuff that other people can do... that I never could.",
  ui_story_5081_50810701_35_dialog_content = "Is that why you stay in and play games until you're the best at them?",
  ui_story_5081_50810701_36_dialog_content = "I-It's embarrassing, isn't it?",
  ui_story_5081_50810701_37_dialog_content = "Of course not! In fact, it's an unbelievable achievement!",
  ui_story_5081_50810701_38_dialog_content = "Becoming the best at a single game is an impressive accomplishment for any gamer.",
  ui_story_5081_50810701_39_dialog_content = "But your name is at the top of every leaderboard here—or even all over Astra!",
  ui_story_5081_50810701_40_dialog_content = "\"B\" is already a hero and a symbol in her own right—maybe even a legend! When I came to this store...",
  ui_story_5081_50810701_41_dialog_content = "I did it with the intention of broadening my own horizons too!",
  ui_story_5081_50810701_42_dialog_content = "...",
  ui_story_5081_50810701_43_dialog_content = "B-But you didn't come here with the intention of playing games.",
  ui_story_5081_50810701_44_dialog_content = "Haha, that's true! When I first showed up, my goal was clear—to find my lost friend Gronru.",
  ui_story_5081_50810701_45_dialog_content = "You see, she was the one who introduced me to a lot of games.",
  ui_story_5081_50810701_46_dialog_content = "Most of the time, I just accepted them because she gave them to me.",
  ui_story_5081_50810701_47_dialog_content = "And I would only play them because they came from a friend.",
  ui_story_5081_50810701_48_dialog_content = "That's why I never imagined that I would like an arcade as much as I do now.",
  ui_story_5081_50810701_49_dialog_content = "When I think about all the matches we played today...",
  ui_story_5081_50810701_50_dialog_content = "I realize just how much fun I've been having here.",
  ui_story_5081_50810701_51_dialog_content = "Hmm... I understand.",
  ui_story_5081_50810701_52_dialog_content = "You really are capable of enjoying video games.",
  ui_story_5081_50810701_53_dialog_content = "I don't know if it's because of my history, my goals, or maybe some of the responsibilities I'm shouldering...",
  ui_story_5081_50810701_54_dialog_content = "But... it's a little hard for me to accept that I like this sort of thing.",
  ui_story_5081_50810701_55_dialog_content = "So being able to play video games like this, without any fear of judgement, helps me face that inner conflict head-on...",
  ui_story_5081_50810701_56_dialog_content = "If I can purely enjoy games like you and Gronru, I bet we'll be able to understand each other even more.",
  ui_story_5081_50810701_57_dialog_content = "<size=30>Gronru... I'm so jealous that she has a friend like you...</size>",
  ui_story_5081_50810701_58_dialog_content = "So you do know her?",
  ui_story_5081_50810701_59_dialog_content = "S-Sort of... She's a veteran gamer after all, and she's made lots of special contributions to the community.",
  ui_story_5081_50810701_60_dialog_content = "B-But that's all I know about her... Please don't ask me any more questions!",
  ui_story_5081_50810701_61_dialog_content = "Wow... Those two are gorgeous!",
  ui_story_5081_50810701_62_dialog_content = "Oh! Uh, did you hear that? It sounds like we might have some new challengers in the arcade!",
  ui_story_5081_50810701_63_dialog_content = "W-We should probably go see it!",
  ui_story_5081_50810701_64_dialog_content = "(She's asking to meet the challengers herself? That's a rare sight...)",
  ui_story_5081_50810701_65_dialog_content = "(It seems like she's dodging the topic. Could she be talking about Gronru?)",
  ui_story_5081_50810701_66_dialog_content = "(As suspicious as it seems, I think playing games is my best shot at finding out more.)",
  ui_story_5081_50810701_67_dialog_content = "Sure, let's head over there!",
  ui_story_5081_50810701_68_dialog_content = "<color=#e8d9bb>By that point, two challengers with very unique styles have already drawn the attention of the entire arcade.</color>",
  ui_story_5081_50810701_69_dialog_content = "<color=#e8d9bb>One of them is sitting on the sofa in a cool fashion.</color>",
  ui_story_5081_50810701_70_dialog_content = "Is this store designed to look so retro on purpose?",
  ui_story_5081_50810701_71_dialog_content = "The lights and decorations are all with style, and they've been placed so perfectly throughout the arcade.",
  ui_story_5081_50810701_72_dialog_content = "I can't wait to go all out for this challenge!",
  ui_story_5081_50810701_73_dialog_content = "<color=#e8d9bb>The other is hopping around the store excitedly like a rabbit.</color>",
  ui_story_5081_50810701_74_dialog_content = "Wow, is this a claw machine? The prizes inside are sooo cute!",
  ui_story_5081_50810701_75_dialog_content = "And this must be where you exchange points for prizes! Oh, I want everything they have...",
  ui_story_5081_50810701_76_dialog_content = "Say, can I take home every single prize if I keep winning?",
  ui_story_5081_50810701_77_dialog_content = "Humph!",
  ui_story_5081_50810701_78_dialog_content = "Of course you can. The trick is winning that many times first.",
  ui_story_5081_50810701_79_dialog_content = "But that won't be necessary. As the arcade's owner, I have the final say around here.",
  ui_story_5081_50810701_80_dialog_content = "If you're able to beat me in a game, you can take whatever you want, and as much of it as you want.",
  ui_story_5081_50810701_81_dialog_content = "Oh? Now we're talking...",
  ui_story_5081_50810701_82_dialog_content = "I've heard about the legendary gamer \"B\" and her arcade, but I never expected her to be this bold. I like it!",
  ui_story_5081_50810701_83_dialog_content = "Wow, that's super generous of you! In that case... I'm gonna do my best to beat you!",
  ui_story_5081_50810701_84_dialog_content = "Wow! It looks like we have some new challengers! Let's give it up for Wild Witch and Cutie Cake!",
  ui_story_5081_50810701_85_dialog_content = "The two players will make their challenges at the same time! <size=30>But my question is, who exactly are they? An arrogant go-getter and a merchandise collector?</size>",
  ui_story_5081_50810701_86_dialog_content = "Let's get pumped up for another exciting match below—",
  ui_story_5081_50810702_1_dialog_content = "Looks like video game fire doesn't burn as hot as real flames...",
  ui_story_5081_50810702_2_dialog_content = "I've done my best too! Looks like I'll have to buy all this cute stuff for myself...",
  ui_story_5081_50810702_3_dialog_content = "Say, Mr. Crocodile, could I try on that badge for a second?",
  ui_story_5081_50810702_4_dialog_content = "I'm sorry miss, but you have to exchange tokens for that.",
  ui_story_5081_50810702_5_dialog_content = "Oh, okay! I'll go get some right now!",
  ui_story_5081_50810702_6_dialog_content = "... And she just ran away?",
  ui_story_5081_50810702_7_dialog_content = "Say, you wouldn't be interested in teaming up with me, would you?",
  ui_story_5081_50810702_8_dialog_content = "With the legendary gamer \"B\" at my side, we could start a whole new era of gaming in the world!",
  ui_story_5081_50810702_9_dialog_content = "When that day comes, your arcade might get overrun with all the new customers you'll have!",
  ui_story_5081_50810702_10_dialog_content = "I... Uh... Although growing the gaming community isn't necessarily a bad thing...",
  ui_story_5081_50810702_11_dialog_content = "I've never done anything that extreme, and... and I really don't want to either! Sorry...",
  ui_story_5081_50810702_12_dialog_content = "Strong but humble, and sticking to what you know, eh?",
  ui_story_5081_50810702_13_dialog_content = "That's fine. What matters most is that you managed to catch my attention.",
  ui_story_5081_50810702_14_dialog_content = "Look me up whenever you feel like teaming up.",
  ui_story_5081_50810702_15_dialog_content = "D-Do you also have one of those?",
  ui_story_5081_50810702_16_dialog_content = "One of what?",
  ui_story_5081_50810702_17_dialog_content = "A card with your name on it. I got one earlier.",
  ui_story_5081_50810702_18_dialog_content = "She means a business card.",
  ui_story_5081_50810702_19_dialog_content = "Haha, of course I have one! Here you go, hope to hear from you soon.",
  ui_story_5081_50810702_20_dialog_content = "Phew...",
  ui_story_5081_50810702_21_dialog_content = "I'd say that went pretty smoothly, all things considered...",
  ui_story_5081_50810702_22_dialog_content = "Why didn't you ask if they were having fun this time?",
  ui_story_5081_50810702_23_dialog_content = "Uh...",
  ui_story_5081_50810702_24_dialog_content = "D-Did I ask the wrong question again?",
  ui_story_5081_50810702_25_dialog_content = "E-Even for someone like me, it's easy to see that they did have fun playing that game...",
  ui_story_5081_50810702_26_dialog_content = "But when I watched them in-game just now...",
  ui_story_5081_50810702_27_dialog_content = "They didn't seem as excited or as immersed as you, did they?",
  ui_story_5081_50810702_28_dialog_content = "You got so upset with me because I didn't have my head in the game... I hope they didn't upset you too!",
  ui_story_5081_50810702_29_dialog_content = "Not really, no. Those two are more of the social type when it comes to gaming.",
  ui_story_5081_50810702_30_dialog_content = "Do you remember what that antique connoisseur said earlier?",
  ui_story_5081_50810702_31_dialog_content = "Something about video games being the fusion of technology and entertainment, right?",
  ui_story_5081_50810702_32_dialog_content = "Yes. Video games are so much more than something to be played.",
  ui_story_5081_50810702_33_dialog_content = "A good game is like a work of art—every single aspect of it has the potential to draw in players.",
  ui_story_5081_50810702_34_dialog_content = "Some people play for the story and focus on the finer details of the in-game world.",
  ui_story_5081_50810702_35_dialog_content = "Others are more interested in the artwork and design of a game and even invite other people to role-play with them.",
  ui_story_5081_50810702_36_dialog_content = "Sometimes, themed games like that generate huge waves of interest. That's how lots of people become gamers in the first place.",
  ui_story_5081_50810702_37_dialog_content = "There's more to gaming than just beating levels...",
  ui_story_5081_50810702_38_dialog_content = "That's why people who aren't focused on winning are also worthy of enjoying games.",
  ui_story_5081_50810702_39_dialog_content = "Odi mentioned something similar earlier today. She said that the most important part of a video game is the player.",
  ui_story_5081_50810702_40_dialog_content = "I agree. It's hard for players to find joy in video games when they stay away from the gaming community.",
  ui_story_5081_50810702_41_dialog_content = "That's why I let Gronru convince me to take over this arcade...",
  ui_story_5081_50810702_42_dialog_content = "Gronru again, huh?",
  ui_story_5081_50810702_43_dialog_content = "D-Did I say that? Sorry, I didn't mean to bring her up again! Just forget about it!",
  ui_story_5081_50810702_44_dialog_content = "Yeah, I know the drill. I won't pry any further, I promise.",
  ui_story_5081_50810702_45_dialog_content = "Despite how much you tend to downplay things, I think this is something only you can achieve...",
  ui_story_5081_50810702_46_dialog_content = "Wh-What's that?",
  ui_story_5081_50810702_47_dialog_content = "Running this arcade and giving gamers a place to relax and have fun.",
  ui_story_5081_50810702_48_dialog_content = "Who else but the legendary \"B\" could've done it so well?",
  ui_story_5081_50810702_49_dialog_content = "B-But I'm not good at socializing with people at all! I don't think I'm fit to give gamers any kind of positive experience...",
  ui_story_5081_50810702_50_dialog_content = "I'm just providing a venue, that's all.",
  ui_story_5081_50810702_51_dialog_content = "Is that what you think?",
  ui_story_5081_50810702_52_dialog_content = "Because to me, it seemed like you interacted with today's challengers just fine.",
  ui_story_5081_50810702_53_dialog_content = "There's a reason people respect you and gather around this place, you know?",
  ui_story_5081_50810702_54_dialog_content = "I'm not that special... and even if you compliment me, I still won't tell you—",
  ui_story_5081_50810702_55_dialog_content = "Tell me what?",
  ui_story_5081_50810702_56_dialog_content = "Boss! We have another new visitor!",
  ui_story_5081_50810702_57_dialog_content = "Is it a challenger? I'll be right there...",
  ui_story_5081_50810702_58_dialog_content = "Not exactly...",
  ui_story_5081_50810702_59_dialog_content = "He's wearing an Illumina uniform, and he talks like he's following a script. I don't think he's any sort of gamer. Also...",
  ui_story_5081_50810702_60_dialog_content = "You didn't get on somebody's bad side recently, did you PlayerName?",
  ui_story_5081_50810702_61_dialog_content = "Because that guy asked for you by name!",
  ui_story_5081_50810801_1_dialog_content = "Someone in an Illumina uniform is looking for me? Don't tell me...",
  ui_story_5081_50810801_2_dialog_content = "Oh...",
  ui_story_5081_50810801_3_dialog_content = "You're finally here, PlayerName. Might I have a word with you, please?",
  ui_story_5081_50810801_4_dialog_content = "Sure... Don't worry, everyone's too busy playing games to notice us.",
  ui_story_5081_50810801_5_dialog_content = "Good to see you again, Intelligence Officer Anatoli.",
  ui_story_5081_50810801_6_dialog_content = "Likewise, PlayerName. I'll get right to the point.",
  ui_story_5081_50810801_7_dialog_content = "First, allow me to thank you for your efforts in assisting Illumina during this critical time.",
  ui_story_5081_50810801_8_dialog_content = "If I may ask, how is your investigation proceeding?",
  ui_story_5081_50810801_9_dialog_content = "To put it one way, I've beaten about five of the eight gyms...",
  ui_story_5081_50810801_10_dialog_content = "I see. You mean to say that your mission is sixty-two point five percent complete?",
  ui_story_5081_50810801_11_dialog_content = "Well, I have to beat the Elite Four too...",
  ui_story_5081_50810801_12_dialog_content = "Might I ask you to explain things in layman's terms?",
  ui_story_5081_50810801_13_dialog_content = "Haha... It's kind of hard to quantify progress when you're searching for someone.",
  ui_story_5081_50810801_14_dialog_content = "But I've been doing my best to carry out this mission for Migard and the Committee! Trust me, I'll get it done!",
  ui_story_5081_50810801_15_dialog_content = "Is that so? Again, I thank you for your contributions to Illumina.",
  ui_story_5081_50810801_16_dialog_content = "According to my intelligence, this place does have some very attractive games in store.",
  ui_story_5081_50810801_17_dialog_content = "Coupled with this comfortable atmosphere, it's the perfect place to forget one's worries and lose one's self in virtual worlds.",
  ui_story_5081_50810801_18_dialog_content = "When I was waiting for you, I was worried that you had lost yourself to these worlds as well... but it seems I was overthinking things.",
  ui_story_5081_50810801_19_dialog_content = "I'd never lose sight of a mission this important! You really shouldn't joke like that, Anatoli! Hahaha...",
  ui_story_5081_50810801_20_dialog_content = "So did you only come here to get a status report for Migard?",
  ui_story_5081_50810801_21_dialog_content = "To be frank, no. In fact, one might say we have a bit of a conflict between us.",
  ui_story_5081_50810801_22_dialog_content = "Conflict?",
  ui_story_5081_50810801_23_dialog_content = "It's nothing to be concerned about. When it comes to the mission, our goals are still the same.",
  ui_story_5081_50810801_24_dialog_content = "The players here are far more interested in ancient technology than most people. I believe I could gather some very interesting information from them.",
  ui_story_5081_50810801_25_dialog_content = "... If only I could stay a bit longer.",
  ui_story_5081_50810801_26_dialog_content = "If that's how you feel, then why don't we find something for you to play?",
  ui_story_5081_50810801_27_dialog_content = "Well, there is one game that has piqued my interest.",
  ui_story_5081_50810801_28_dialog_content = "The one named Eclipsite Crisis.",
  ui_story_5081_50810801_29_dialog_content = "The Eclipsites in this game are supposed to be quite realistic, as well as the weapons that are available to players.",
  ui_story_5081_50810801_30_dialog_content = "I sometimes wonder if it was developed from a failed Illumina training program.",
  ui_story_5081_50810801_31_dialog_content = "Why don't you try it out then? I still have plenty of tokens, after all.",
  ui_story_5081_50810801_32_dialog_content = "I think I will. Your generosity is very much appreciated.",
  ui_story_5081_50810801_33_dialog_content = "<color=#e8d9bb>Tap, tap, tap, tap—</color>",
  ui_story_5081_50810801_34_dialog_content = "<color=#e8d9bb>Boom!</color>",
  ui_story_5081_50810801_35_dialog_content = "Graah...",
  ui_story_5081_50810801_36_dialog_content = "The controls are surprisingly fluid and responsive! Very challenging for players!",
  ui_story_5081_50810801_37_dialog_content = "<color=#e8d9bb>Tap, tap, tap, tap—</color>",
  ui_story_5081_50810801_38_dialog_content = "The combat is so realistic too! Unfortunately, tokens can't be used to revive our fallen comrades in real life...",
  ui_story_5081_50810801_39_dialog_content = "...",
  ui_story_5081_50810801_40_dialog_content = "Huh? You haven't finished the level yet, Anatoli.",
  ui_story_5081_50810801_41_dialog_content = "I didn't come here to play games. I only wanted to try them briefly for myself.",
  ui_story_5081_50810801_42_dialog_content = "And now that I have, I can't help but feel a bit remorseful.",
  ui_story_5081_50810801_43_dialog_content = "Remorseful?",
  ui_story_5081_50810801_44_dialog_content = "This game has the potential to serve as a proper training program and aid us greatly in future battles...",
  ui_story_5081_50810801_45_dialog_content = "But it seems the players here only value it as a source of entertainment.",
  ui_story_5081_50810801_46_dialog_content = "It makes me wonder, if so many people find such joy in destroying Eclipsites in games...",
  ui_story_5081_50810801_47_dialog_content = "Wouldn't their time and energy be better spent wiping out actual Eclipsites on the battlefield?",
  ui_story_5081_50810801_48_dialog_content = "Is this truly the value of Astra's video games? Perhaps I don't fully understand it, but it seems like a waste of—",
  ui_story_5081_50810801_49_dialog_content = "<color=#e8d9bb>Tap, tap, tap, tap—</color>",
  ui_story_5081_50810801_50_dialog_content = "Huh? It's—",
  ui_story_5081_50810801_51_dialog_content = "Abandoning a game when it's still not finished... If anyone's being wasteful, it's you.",
  ui_story_5081_50810801_52_dialog_content = "I won't allow this kind of behavior in my arcade.",
  ui_story_5081_50810801_53_dialog_content = "Your arcade, you say? You must be the owner.",
  ui_story_5081_50810801_54_dialog_content = "Forgive me if I violated your establishment's rules. I'll be sure to finish playing from now on.",
  ui_story_5081_50810801_55_dialog_content = "You're a soldier from Illumina, aren't you?",
  ui_story_5081_50810801_56_dialog_content = "Indeed I am.",
  ui_story_5081_50810801_57_dialog_content = "Then muster all of your skill and training experience—try to beat my score!",
  ui_story_5081_50810801_58_dialog_content = "I have no desire to compete, but if this is what you wish...",
  ui_story_5081_50810801_59_dialog_content = "<color=#e8d9bb>Tap, tap, tap—tap, tap, tap, tap</color>",
  ui_story_5081_50810801_60_dialog_content = "<color=#e8d9bb>Boom! Boom!</color>",
  ui_story_5081_50810801_61_dialog_content = "<color=#e8d9bb>Boom!</color>",
  ui_story_5081_50810801_62_dialog_content = "A-Amazing! They're playing as if they're possessed by monsters!",
  ui_story_5081_50810801_63_dialog_content = "But Anatoli... Somehow, his score is far lower than hers!",
  ui_story_5081_50810801_64_dialog_content = "I don't think... I've seen her play this seriously before...",
  ui_story_5081_50810801_65_dialog_content = "In your opinion... am I unworthy of this?",
  ui_story_5081_50810801_66_dialog_content = "... Pardon, but are you talking to me?",
  ui_story_5081_50810801_67_dialog_content = "Yes. As someone who can't fight Eclipsites in real life... Do you think I have the right to fight them in a video game?",
  ui_story_5081_50810801_68_dialog_content = "Isn't it possible that some people just weren't born to battle Eclipsites... or even leave the safety of their homes?",
  ui_story_5081_50810801_69_dialog_content = "But even so, maybe they still want to make a stand against the monsters that have overrun our world...",
  ui_story_5081_50810801_70_dialog_content = "Even if it's just by giving everyone a place to come together and have fun.",
  ui_story_5081_50810801_71_dialog_content = "A person like that... still has something to offer the world, don't you think?",
  ui_story_5081_50810801_72_dialog_content = "I...",
  ui_story_5081_50810801_73_dialog_content = "Don't lose focus or you'll lose.",
  ui_story_5081_50810801_74_dialog_content = "Forgive me.",
  ui_story_5081_50810801_75_dialog_content = "I'll concentrate all of my strength on finishing this game...",
  ui_story_5081_50810802_1_dialog_content = "<color=#e8d9bb>Mission Completed!</color>",
  ui_story_5081_50810802_2_dialog_content = "Is it over now? I can hardly believe that so much time has already passed.",
  ui_story_5081_50810802_3_dialog_content = "Or that I lost by such a large margin...",
  ui_story_5081_50810802_4_dialog_content = "I must admit, your shooting prowess is just as keen as your proficiency in video games.",
  ui_story_5081_50810802_5_dialog_content = "I believe your skills are surpassed only by Aurorians who have undergone Officer Yingel's special combat training...",
  ui_story_5081_50810802_6_dialog_content = "Did you have fun?",
  ui_story_5081_50810802_7_dialog_content = "Hmm?",
  ui_story_5081_50810802_8_dialog_content = "Why, yes! If I had to assess the quality of this game, I would give it the highest possible rating.",
  ui_story_5081_50810802_9_dialog_content = "But could you please tell me why you're still playing it?",
  ui_story_5081_50810802_10_dialog_content = "Oh! Don't mind me, I'm just clearing the rest of the side missions... It bothers me if I don't finish an entire game.",
  ui_story_5081_50810802_11_dialog_content = "And also... I-I feel a lot braver when talking to people if I'm looking at a screen!",
  ui_story_5081_50810802_12_dialog_content = "Not everyone gets the opportunity to fight Eclipsites on the front lines.",
  ui_story_5081_50810802_13_dialog_content = "Some people work the fields, while others build up defenses...",
  ui_story_5081_50810802_14_dialog_content = "Some fly all over Astra delivering important messages, and some stay in their labs solving technical problems...",
  ui_story_5081_50810802_15_dialog_content = "But I think everyone deserves a chance to relax and decompress, as well as a chance to challenge themselves!",
  ui_story_5081_50810802_16_dialog_content = "Something that helps them understand the danger of Eclipsites while also renewing their desire to work toward a common goal...",
  ui_story_5081_50810802_17_dialog_content = "Don't you think it's a good way to connect the Aurorians who can't fight Eclipsites with those who can?",
  ui_story_5081_50810802_18_dialog_content = "What, exactly?",
  ui_story_5081_50810802_19_dialog_content = "She's talking about the game you just played, Anatoli.",
  ui_story_5081_50810802_20_dialog_content = "I saw your expressions while you were playing too...",
  ui_story_5081_50810802_21_dialog_content = "Serious, diligent, proud of your achievements, and bothered by your failures.",
  ui_story_5081_50810802_22_dialog_content = "Those emotions are no different than the ones you experience outside of gaming, which is why you should give Batia an honest answer.",
  ui_story_5081_50810802_23_dialog_content = "Do you truly think that things are only worthwhile if they can be used in the struggle against Eclipsites?",
  ui_story_5081_50810802_24_dialog_content = "...",
  ui_story_5081_50810802_25_dialog_content = "Please forgive me for not realizing my mistake sooner...",
  ui_story_5081_50810802_26_dialog_content = "Some of the things I just said... were meant for people who aren't even here right now.",
  ui_story_5081_50810802_27_dialog_content = "Perhaps I was trying to vent my stress and frustration toward them.",
  ui_story_5081_50810802_28_dialog_content = "Please allow me to use the knowledge I gained while playing this game to rectify my answer.",
  ui_story_5081_50810802_29_dialog_content = "Sure, go ahead.",
  ui_story_5081_50810802_30_dialog_content = "Video games are not worthless—far from it, in fact.",
  ui_story_5081_50810802_31_dialog_content = "The atmosphere of this arcade is a direct reflection of Illumina's original mission.",
  ui_story_5081_50810802_32_dialog_content = "Our endless struggles and sacrifices, are they not for the purpose of creating a peaceful world, free from the threat of Eclipsites?",
  ui_story_5081_50810802_33_dialog_content = "A world where those who cannot defend themselves from Eclipsites can also have long and happy lives...",
  ui_story_5081_50810802_34_dialog_content = "The countless sacrifices we've made up until this point are what truly matter.",
  ui_story_5081_50810802_35_dialog_content = "To struggle and sacrifice simply for the sake of doing so is to lose sight of our goals and desires.",
  ui_story_5081_50810802_36_dialog_content = "Ah... My apologies for giving such a lengthy response.",
  ui_story_5081_50810802_37_dialog_content = "But my heart and mind are greatly comforted now... Thank you, PlayerName and Miss Batia.",
  ui_story_5081_50810802_38_dialog_content = "...",
  ui_story_5081_50810802_39_dialog_content = "I didn't say a thing, you know. Maybe this was something the game was meant to show you?",
  ui_story_5081_50810802_40_dialog_content = "Indeed, I never once considered the thoughts and feelings of those who cannot fight Eclipsites prior to playing this game.",
  ui_story_5081_50810802_41_dialog_content = "But now I feel I have gained a slightly better understanding.",
  ui_story_5081_50810802_42_dialog_content = "I must maintain a more open-minded approach when gathering intelligence from now on...",
  ui_story_5081_50810802_43_dialog_content = "Don't forget to relax and enjoy yourself every now and then! You're always welcome at the arcade!",
  ui_story_5081_50810802_44_dialog_content = "Thank you. I just wish Officer Yingel could see things this way as well.",
  ui_story_5081_50810802_45_dialog_content = "<size=30>She's been pushing herself so hard lately, perhaps more than necessary.</size>",
  ui_story_5081_50810802_46_dialog_content = "... But not to worry. I will ensure that this matter reaches a satisfactory conclusion.",
  ui_story_5081_50810802_47_dialog_content = "Uh, what matter?",
  ui_story_5081_50810802_48_dialog_content = "I'll contact you once it has been resolved, rest assured.",
  ui_story_5081_50810802_49_dialog_content = "Until then, please wait patiently for my good news...",
  ui_story_5081_50810802_50_dialog_content = "... Is he gone?",
  ui_story_5081_50810802_51_dialog_content = "Yeah... And it feels like he hid something important from us.",
  ui_story_5081_50810802_X51_dialog_content = "(After seeing Jomu off with Odi and helping Batia with some chores, the day was nearly over.)",
  ui_story_5081_50810802_X52_dialog_content = "(Customers were leaving for the night. When Batia and I were the only ones left in the arcade, we decided to close up shop and go for a walk outside.)",
  ui_story_5081_50810802_X53_dialog_content = "Thank you...",
  ui_story_5081_50810802_X54_dialog_content = "What are you thanking me for this time?",
  ui_story_5081_50810802_52_dialog_content = "For lots of things! First off, thank you for helping me talk to that soldier from Illumina... But I have to ask...",
  ui_story_5081_50810802_53_dialog_content = "What I said to him just now... Did I go too far?",
  ui_story_5081_50810802_54_dialog_content = "After all... I-I'm just a worthless shut-in who only knows how to play games...",
  ui_story_5081_50810802_55_dialog_content = "That's the reason I value games like this, so I...",
  ui_story_5081_50810802_56_dialog_content = "You didn't go too far, so stop doubting yourself so much!",
  ui_story_5081_50810802_57_dialog_content = "I don't think there's a single Aurorian on Astra who's worse than me at fighting Eclipsites.",
  ui_story_5081_50810802_58_dialog_content = "But does that mean my existence has no value?",
  ui_story_5081_50810802_59_dialog_content = "N-No... That's not what I meant at all! It's just...",
  ui_story_5081_50810802_60_dialog_content = "That intelligence officer made a lot of good points too... I shouldn't have questioned him like that.",
  ui_story_5081_50810802_61_dialog_content = "But you know... I'm actually kind of excited to see the future he spoke about...",
  ui_story_5081_50810802_62_dialog_content = "A world free from the threat of Eclipsites... It's hard to imagine something so wonderful.",
  ui_story_5081_50810802_63_dialog_content = "If that day ever comes, then maybe the Joint Military Exercise will turn into Astra's biggest gaming convention!",
  ui_story_5081_50810802_64_dialog_content = "I bet you'd look so cool standing on the winner's platform and holding the first-place trophies for every single game—",
  ui_story_5081_50810802_65_dialog_content = "Stop it! I could never go up there to accept a trophy... That's Gronru's thing, not mine!",
  ui_story_5081_50810802_66_dialog_content = "But until the world is finally rid of Eclipsites...",
  ui_story_5081_50810802_67_dialog_content = "I may want to play a game where I can face them with a team of powerful Aurorians...",
  ui_story_5081_50810802_68_dialog_content = "And ultimately defeat them all!",
  ui_story_5081_50810802_69_dialog_content = "Even though a single video game could never capture all of Astra's struggles...",
  ui_story_5081_50810802_70_dialog_content = "I still want to experience and understand those stories for myself!",
  ui_story_5081_50810802_71_dialog_content = "You will.",
  ui_story_5081_50810802_72_dialog_content = "Huh?",
  ui_story_5081_50810802_73_dialog_content = "I know you will! And if you can't do it on your own, just ask Gronru to make more games for you!",
  ui_story_5081_50810802_74_dialog_content = "If she includes all of us and our stories, I bet it would be one of the greatest games ever!",
  ui_story_5081_50810802_75_dialog_content = "Ask her to make more games? But Gronru has it so hard right now...",
  ui_story_5081_50810802_76_dialog_content = "B-Boss! Come quick!",
  ui_story_5081_50810802_77_dialog_content = "Trouble! Trouble! Chirp!",
  ui_story_5081_50810802_78_dialog_content = "Unbelievable... This is unbelievable!",
  ui_story_5081_50810802_79_dialog_content = "What's going on?",
  ui_story_5081_50810802_80_dialog_content = "The final boss of all challengers just showed up!",
  ui_story_5081_50810802_81_dialog_content = "And with those tentacles, she definitely looks the part... If you're not careful...",
  ui_story_5081_50810802_82_dialog_content = "The legend of \"B\" will be completely ruined! Chirp!",
  ui_story_5081_50810901_1_dialog_content = "I-Incredible...",
  ui_story_5081_50810901_2_dialog_content = "She's playing five games at the same time... No, six!",
  ui_story_5081_50810901_3_dialog_content = "And she's absolutely crushing them!",
  ui_story_5081_50810901_4_dialog_content = "This playstyle is nothing like what I've ever seen before! It's like she was created with a single purpose...",
  ui_story_5081_50810901_5_dialog_content = "<size=45>An ultimate weapon built solely to destroy legends!</size>",
  ui_story_5081_50810901_6_dialog_content = "No, no...",
  ui_story_5081_50810901_7_dialog_content = "She's not some ultimate weapon or anything. She's just a special kind of Aurorian...",
  ui_story_5081_50810901_8_dialog_content = "...",
  ui_story_5081_50810901_9_dialog_content = "No. 33, what brings you here? Did you come to play some games?",
  ui_story_5081_50810901_10_dialog_content = "... Caelestite?",
  ui_story_5081_50810901_11_dialog_content = "One moment, please. I will explain my presence once I complete the task at hand.",
  ui_story_5081_50810901_12_dialog_content = "<color=#e8d9bb>No. 33's tentacles slowly come to a stop, and the data displayed in her eyes eventually disappears.</color>",
  ui_story_5081_50810901_13_dialog_content = "<color=#e8d9bb>The arcade machines around her flash with victory messages, and her scores appear on all of their leaderboards.</color>",
  ui_story_5081_50810901_14_dialog_content = "<color=#e8d9bb>However, there is still a clear gap between her scores and the ones sitting at the very top.</color>",
  ui_story_5081_50810901_15_dialog_content = "Now that the games are over, allow me to explain my reasons for coming here.",
  ui_story_5081_50810901_16_dialog_content = "My name is No. 33, a guardian of Northland's ancient ruins.",
  ui_story_5081_50810901_17_dialog_content = "It has come to my attention that a data cartridge from the ancient civilization has been discovered and restored in this place. As such, I requested permission from the Northland Court to travel here.",
  ui_story_5081_50810901_18_dialog_content = "My original intent was to purchase it and analyze its contents.",
  ui_story_5081_50810901_19_dialog_content = "Upon arriving at this arcade, however, I quickly realized that all of these games were created by restoring ancient data...",
  ui_story_5081_50810901_20_dialog_content = "And that their files were still worthy of analysis.",
  ui_story_5081_50810901_21_dialog_content = "For this reason, I immediately began conducting research on them. I am prepared to offer payment for the data I have gathered and any costs I may have incurred.",
  ui_story_5081_50810901_22_dialog_content = "Th-That won't be necessary. These games are meant to be played, and you already spent tokens to play them.",
  ui_story_5081_50810901_23_dialog_content = "But using tentacles to play multiple games... I've never seen anything like that before...",
  ui_story_5081_50810901_24_dialog_content = "Are they easy to use?",
  ui_story_5081_50810901_25_dialog_content = "Do you mean my tentacles? They are part of the guardian system and allow me to manage various structures within the ruins.",
  ui_story_5081_50810901_26_dialog_content = "They are not particularly useful for everyday Aurorian life, but they are indeed helpful when executing orders.",
  ui_story_5081_50810901_27_dialog_content = "And now, I realize that they are also quite suitable for playing video games. Compared to other players in the arcade...",
  ui_story_5081_50810901_28_dialog_content = "The responsiveness, accuracy, and sensitivity of my tentacles offer me clear advantages, but intimate knowledge of game data is also quite essential.",
  ui_story_5081_50810901_29_dialog_content = "Is that the reason you weren't able to secure the highest score just now, No. 33?",
  ui_story_5081_50810901_30_dialog_content = "Or is it just because this was your first time playing? Maybe you'll be able to top the leaderboards once you get the hang of these games!",
  ui_story_5081_50810901_31_dialog_content = "I must acquire more experience before arriving at any definitive conclusions.",
  ui_story_5081_50810901_32_dialog_content = "The more complex the game, the more difficult it becomes, but it also contains even more optimal paths for completion.",
  ui_story_5081_50810901_33_dialog_content = "As for the scores on these leaderboards, I have no way of analyzing them at this time.",
  ui_story_5081_50810901_34_dialog_content = "I can only look upon them with respect.",
  ui_story_5081_50810901_35_dialog_content = "That's perfect! Then... That means you still need to gather more game data, right?",
  ui_story_5081_50810901_36_dialog_content = "Why not play with us and gain even more experience?",
  ui_story_5081_50810901_37_dialog_content = "Of course. My new orders are to observe modern Aurorians in their day-to-day lives...",
  ui_story_5081_50810901_38_dialog_content = "As well as to ensure the safety of their future using any useful data from the ancient civilization.",
  ui_story_5081_50810901_39_dialog_content = "Allying myself with the players present would be an efficient way to carry out my orders.",
  ui_story_5081_50810901_40_dialog_content = "I can begin at any time.",
  ui_story_5081_50810901_41_dialog_content = "Come on, everyone! Let's have some fun!",
  ui_story_5081_50810902_1_dialog_content = "<color=#e8d9bb>With Batia's planning, everyone begins playing games against No. 33.</color>",
  ui_story_5081_50810902_2_dialog_content = "<color=#e8d9bb>With the exception of Odi, who manages to win one or two matches, No. 33 defeats everyone in stunning fashion.</color>",
  ui_story_5081_50810902_3_dialog_content = "<color=#e8d9bb>Batia, however, maintains her title as the legendary and undefeated \"B.\"</color>",
  ui_story_5081_50810902_4_dialog_content = "Thank you, everyone. The data and observations I have gathered today will be most valuable to my research.",
  ui_story_5081_50810902_5_dialog_content = "Pardon me, but may I borrow a few games which require lengthy analysis to complete?",
  ui_story_5081_50810902_6_dialog_content = "I believe that the data concealed within these games will be of great benefit to the future of all Aurorians.",
  ui_story_5081_50810902_7_dialog_content = "I will analyze them to the fullest extent and make my findings available to everyone.",
  ui_story_5081_50810902_8_dialog_content = "Of course! Come with me, and I'll take you to see my collection! Take whatever you think will help!",
  ui_story_5081_50810902_9_dialog_content = "I will choose wisely. Thank you for your generosity.",
  ui_story_5081_50810902_10_dialog_content = "I don't think I've ever seen you this excited, Batia...",
  ui_story_5081_50810902_11_dialog_content = "Oh, r-really? Is it that obvious?",
  ui_story_5081_50810902_12_dialog_content = "Yeah, but I feel exactly the same way as you right now.",
  ui_story_5081_50810902_13_dialog_content = "At the end of the day, video games are a great way to bring people together and cheer them up, huh?",
  ui_story_5081_50810902_14_dialog_content = "Who knows? Once No. 33 analyzes the data in those games, maybe her findings will help the gaming industry develop even further.",
  ui_story_5081_50810902_15_dialog_content = "She even said the future of all Aurorians might benefit from your games... That's pretty exciting, isn't it?",
  ui_story_5081_50810902_16_dialog_content = "You really like video games, PlayerName!",
  ui_story_5081_50810902_17_dialog_content = "Advancing games and making them more accessible to the world... That's the best thing I could ever ask for.",
  ui_story_5081_50810902_18_dialog_content = "I can't wait to see what she finds...",
  ui_story_5081_50810902_19_dialog_content = "I have made my selection. When the results of my research are clear, I will notify you as soon as possible, miss.",
  ui_story_5081_50810902_20_dialog_content = "B-Best of luck!",
  ui_story_5081_50810902_21_dialog_content = "I must be leaving now. Farewell.",
  ui_story_5081_50810902_22_dialog_content = "A-Actually... Could I ask you something before you go?",
  ui_story_5081_50810902_23_dialog_content = "By all means.",
  ui_story_5081_50810902_24_dialog_content = "It has to do... with the people who made these games—the lost civilization from ages past...",
  ui_story_5081_50810902_25_dialog_content = "Can you tell me what kind of world they lived in?",
  ui_story_5081_50810902_26_dialog_content = "Were there... a lot of games in their world? Games that were developed with more meanings for more than just entertainment?",
  ui_story_5081_50810902_27_dialog_content = "...",
  ui_story_5081_50810902_28_dialog_content = "It was a very advanced world, but also a very terrifying one.",
  ui_story_5081_50810902_29_dialog_content = "\"Meanings,\" you ask?",
  ui_story_5081_50810902_30_dialog_content = "I'm sorry, but analyzing this data will not provide me with the answer you seek.",
  ui_story_5081_50810902_31_dialog_content = "In this world, the meaning of something is not an immutable constant.",
  ui_story_5081_50810902_32_dialog_content = "For those who are cold and starving, anything outside of food and clothing is meaningless.",
  ui_story_5081_50810902_33_dialog_content = "For those with empty souls, abundant material possessions are also meaningless.",
  ui_story_5081_50810902_34_dialog_content = "But in this place, video games are a source of enjoyment, focus, and unity. That makes them meaningful.",
  ui_story_5081_50810902_35_dialog_content = "As far as my orders are concerned, technology that benefits locals is also meaningful.",
  ui_story_5081_50810902_36_dialog_content = "Video games are no exception.",
  ui_story_5081_50810902_37_dialog_content = "So... You think they're meaningful?",
  ui_story_5081_50810902_38_dialog_content = "Yes. <color=#FFB400>In my opinion</color>, they are meaningful.",
  ui_story_5081_50810902_39_dialog_content = "And I believe... you should also see their special meaning <color=#FFB400>in your opinion</color>.",
  ui_story_5081_50810902_40_dialog_content = "Ah...",
  ui_story_5081_50810902_41_dialog_content = "Yeah, I think so too.",
  ui_story_5081_50810902_42_dialog_content = "Players are the ones who give meaning to games, not the games themselves.",
  ui_story_5081_50810902_43_dialog_content = "The most important thing is the people who can find meaning in video games!",
  ui_story_5081_50810902_44_dialog_content = "Whether it's those who collect games, watch the latest trends, or buy gaming merchandise...",
  ui_story_5081_50810902_45_dialog_content = "You were even able to convince Anatoli about the significance of video games!",
  ui_story_5081_50810902_46_dialog_content = "Video games don't distinguish between rich and poor or good and evil. Anyone can find meaning by playing them!",
  ui_story_5081_50810902_47_dialog_content = "PlayerName...",
  ui_story_5081_50810902_48_dialog_content = "If you ever run into someone who describes other people's lives or passions as <color=#FFB400>meaningless</color>...",
  ui_story_5081_50810902_49_dialog_content = "Don't let anything they say affect you! People like that don't care about the meaning or value of anything!",
  ui_story_5081_50810902_50_dialog_content = "I really admire your love for video games, Batia. I just wish you wouldn't doubt yourself so often.",
  ui_story_5081_50810902_51_dialog_content = "Please, keep sharing your love for games with other people. Make your arcade a safe haven for gamers across the world!",
  ui_story_5081_50810902_52_dialog_content = "Ah... Ahhhh! Okay, I get it already! No need for any overkill, PlayerName!",
  ui_story_5081_50810902_53_dialog_content = "Haha, sorry! I was just a little worried about you, so I couldn't help but speak my mind...",
  ui_story_5081_50810902_54_dialog_content = "Thanks. I guess everyone who likes video games is like this.",
  ui_story_5081_50810902_55_dialog_content = "Gronru once told me something like that too...",
  ui_story_5081_50810902_56_dialog_content = "I see... You're actually pretty close to her, aren't you?",
  ui_story_5081_50810902_57_dialog_content = "Yeah... Um, PlayerName? After I close up the arcade for the day, I have some things to tell you...",
  ui_story_5081_50811001_1_dialog_content = "Closing time! Everyone out! Chirp!",
  ui_story_5081_50811001_2_dialog_content = "I know that, now pipe down!",
  ui_story_5081_50811001_3_dialog_content = "Tsk! I'm starting to feel a little uneasy. Did a ball of shadows just pass through the door?",
  ui_story_5081_50811001_4_dialog_content = "Or was it a ball of flames?",
  ui_story_5081_50811001_5_dialog_content = "<color=#e8d9bb>As the sun sets over the horizon, the players slowly return to their homes in blissful ignorance.</color>",
  ui_story_5081_50811001_6_dialog_content = "<color=#e8d9bb>Meanwhile, an ominous silhouette quietly infiltrates this place of joy and amusement.</color>",
  ui_story_5081_50811001_7_dialog_content = "<color=#e8d9bb>Can you sense the disturbing, illusory heat of her presence?</color>",
  ui_story_5081_50811001_8_dialog_content = "The atmosphere suddenly got darker in here... Huh? Who left this horror game on out here?",
  ui_story_5081_50811001_9_dialog_content = "Ah sorry, that was probably me...",
  ui_story_5081_50811001_10_dialog_content = "I was looking for a game to play in my roost tonight, so I might've left a few on.",
  ui_story_5081_50811001_11_dialog_content = "You're not afraid of this game, are you PlayerName?",
  ui_story_5081_50811001_12_dialog_content = "Not really, I just got a little startled when the lines suddenly started playing.",
  ui_story_5081_50811001_13_dialog_content = "Uh, what did you mean by your \"roost\"?",
  ui_story_5081_50811001_14_dialog_content = "Interested? You're free to check it out if you want.",
  ui_story_5081_50811001_15_dialog_content = "Being surrounded by tons of games and blinking lights at night makes me feel so safe and warm...",
  ui_story_5081_50811001_16_dialog_content = "I also have enough snacks and drinks to last me an entire month!",
  ui_story_5081_50811001_17_dialog_content = "Heeheehee...",
  ui_story_5081_50811001_18_dialog_content = "<color=#e8d9bb>Under the cover of night, you fall into the despair of nothingness.</color>",
  ui_story_5081_50811001_19_dialog_content = "<color=#e8d9bb>The howling of tortured souls from beyond the grave echoes through every corner of the dark.</color>",
  ui_story_5081_50811001_20_dialog_content = "Ah...",
  ui_story_5081_50811001_21_dialog_content = "Did you hear that? This game's sound effects sure are realistic...",
  ui_story_5081_50811001_22_dialog_content = "Th-That didn't come from my game!",
  ui_story_5081_50811001_23_dialog_content = "Th-Then what was it?",
  ui_story_5081_50811001_24_dialog_content = "Don't tell me it was...",
  ui_story_5081_50811001_25_dialog_content = "Ah...",
  ui_story_5081_50811001_26_dialog_content = "I think it's coming from over there!",
  ui_story_5081_50811001_27_dialog_content = "B-But that's where my roost is!",
  ui_story_5081_50811001_28_dialog_content = "Hey, wait up!",
  ui_story_5081_50811001_29_dialog_content = "Ahhhhhhh?",
  ui_story_5081_50811001_30_dialog_content = "Ahhhhhhh!",
  ui_story_5081_50811001_31_dialog_content = "A-A ghost! There's a ghost haunting my roost!",
  ui_story_5081_50811001_32_dialog_content = "Ahhhh! PlayerName! Odi! Sork! Bekk! Somebody help me!",
  ui_story_5081_50811001_33_dialog_content = "I never want to play another scary game ever again!",
  ui_story_5081_50811001_34_dialog_content = "Don't worry, I'm coming!",
  ui_story_5081_50811001_35_dialog_content = "Huh? Uriel... Is that you?",
  ui_story_5081_50811001_36_dialog_content = "Crunch! Munch, munch... Glug, glug, glug...",
  ui_story_5081_50811001_37_dialog_content = "Ah. The snacks are nothing special, but these drinks are pretty good...",
  ui_story_5081_50811001_38_dialog_content = "Hey! Don't spill anything on my game machines! Ahhh...",
  ui_story_5081_50811001_39_dialog_content = "Please, I'm not nearly that clumsy. I'm just... helping you clean them off, that's all.",
  ui_story_5081_50811001_40_dialog_content = "Such vile, filthy creatures... with such meaningless lives.",
  ui_story_5081_50811001_41_dialog_content = "Vanish, vanish, vanish, vanish—",
  ui_story_5081_50811001_42_dialog_content = "Vanish together with me, another meaningless existence...",
  ui_story_5081_50811001_43_dialog_content = "I-Is she trying to g-get rid of me in real life? The challenge is for video games only!",
  ui_story_5081_50811001_44_dialog_content = "... I'm pretty sure that's not what she means...",
  ui_story_5081_50811001_45_dialog_content = "She happens to be Uriel... one of the Four Angels of Lumopolis!",
  ui_story_5081_50811001_46_dialog_content = "A famous person from Lumopolis? Wh-What's she doing here?",
  ui_story_5081_50811001_47_dialog_content = "Ahhhh! She's getting crumbs all over my keyboard!",
  ui_story_5081_50811001_48_dialog_content = "I must destroy this world... I must burn it all away...",
  ui_story_5081_50811001_49_dialog_content = "Do you have any idea how long I've been trapped alongside those cursed existences?",
  ui_story_5081_50811001_50_dialog_content = "From dusk till dawn and back to dusk, the heat never stops rising, and I never stop dragging those miserable souls down to hell...",
  ui_story_5081_50811001_51_dialog_content = "It was so painful at first, but now... I feel nothing, so let it all burn...",
  ui_story_5081_50811001_52_dialog_content = "Come with me and descend into the limbo of oblivion...",
  ui_story_5081_50811001_53_dialog_content = "It's starting to get really hot in here!",
  ui_story_5081_50811001_54_dialog_content = "Uriel, you have to calm down!",
  ui_story_5081_50811001_55_dialog_content = "My game machine... She's gonna burn it to ashes! My save file... not my save file!",
  ui_story_5081_50811001_56_dialog_content = "There's no time... We'll just have to cool her down and move everything out of here!",
  ui_story_5081_50811001_57_dialog_content = "Odi! Sork! Bekk! Give us a hand!",
  ui_story_5081_50811002_1_dialog_content = "Is that everything? Phew, I think we managed to save most of it...",
  ui_story_5081_50811002_2_dialog_content = "Do we need to pull anything else out of the room?",
  ui_story_5081_50811002_3_dialog_content = "No, I think we're fine... Thank you, everyone...",
  ui_story_5081_50811002_4_dialog_content = "As for that game machine... just let her have it. It doesn't matter if she burns it...",
  ui_story_5081_50811002_5_dialog_content = "Though Uriel looks really depressed most of the time, I wonder what's gotten into her?",
  ui_story_5081_50811002_6_dialog_content = "Maybe I should ask Carleen to sort this out. After all, Uriel's still a little afraid of her captain.",
  ui_story_5081_50811002_7_dialog_content = "Carleen might even be able to completely cool her off...",
  ui_story_5081_50811002_8_dialog_content = "... How strange.",
  ui_story_5081_50811002_9_dialog_content = "What's strange?",
  ui_story_5081_50811002_10_dialog_content = "She's one of the Four Angels, which means... she's probably eliminated more Eclipsites than any other Aurorian, right?",
  ui_story_5081_50811002_11_dialog_content = "Yeah, I suppose...",
  ui_story_5081_50811002_12_dialog_content = "And yet here she is, hanging out in an arcade and trying her hardest to beat Eclipsites in a video game...",
  ui_story_5081_50811002_13_dialog_content = "Shouldn't a famous warrior from Lumopolis have more noble things to do with her time?",
  ui_story_5081_50811002_14_dialog_content = "She definitely does... Wait, let me rephrase that.",
  ui_story_5081_50811002_15_dialog_content = "When you beat Eclipsites in a video game, you usually get some kind of reward, or it tells you that you beat the level. That doesn't always happen in real life.",
  ui_story_5081_50811002_16_dialog_content = "For a depressed Angel, maybe that's what she wants?",
  ui_story_5081_50811002_17_dialog_content = "I see... I guess everyone has their own reasons for wanting to play games, huh?",
  ui_story_5081_50811002_18_dialog_content = "I'm sure there's a deeper reason behind Uriel's behavior, but that's no excuse for putting you out like this.",
  ui_story_5081_50811002_19_dialog_content = "I'll just let Carleen know—",
  ui_story_5081_50811002_20_dialog_content = "Sorry, everyone!",
  ui_story_5081_50811002_21_dialog_content = "I can't apologize enough for all the trouble we've caused you!",
  ui_story_5081_50811002_22_dialog_content = "Huh? You're here too, PlayerName? Great! That makes things a lot easier!",
  ui_story_5081_50811002_23_dialog_content = "What in the world...",
  ui_story_5081_50811002_24_dialog_content = "There have been a lot more Eclipsites in the area than usual.",
  ui_story_5081_50811002_25_dialog_content = "Uriel got sent out to exterminate them and fought them nonstop for days on end...",
  ui_story_5081_50811002_26_dialog_content = "She's such a hard worker! When she finally clocked out, all she had to say was—",
  ui_story_5081_50811002_27_dialog_content = "\"Sweet destruction... I need to go someplace where I can truly cleanse Eclipsites...\" And then she just suddenly disappeared!",
  ui_story_5081_50811002_28_dialog_content = "I had to ask all over Lumopolis and Umbraton before finding out about this place...",
  ui_story_5081_50811002_29_dialog_content = "A place where she could truly cleanse Eclipsites... She was talking about the games in this arcade! Ah, I'm so jealous!",
  ui_story_5081_50811002_30_dialog_content = "Jealous?",
  ui_story_5081_50811002_31_dialog_content = "Has Lumopolis been really busy lately too?",
  ui_story_5081_50811002_32_dialog_content = "Yup! There are no days off when your job is to ensure everyone's safety, after all...",
  ui_story_5081_50811002_33_dialog_content = "But it looks like Uriel made some trouble for you guys, huh?",
  ui_story_5081_50811002_34_dialog_content = "Is anyone hurt? If so, Lumopolis will bear responsibility for any and all damages!",
  ui_story_5081_50811002_35_dialog_content = "So there's no need to make any nasty reports about what happened here... Okay?",
  ui_story_5081_50811002_36_dialog_content = "Just leave the store's restoration to me!",
  ui_story_5081_50811002_37_dialog_content = "Hah—",
  ui_story_5081_50811002_38_dialog_content = "There we go—",
  ui_story_5081_50811002_39_dialog_content = "Oh—",
  ui_story_5081_50811002_40_dialog_content = "And now it's time... to deal with the most annoying part!",
  ui_story_5081_50811002_41_dialog_content = "Huh? Oh, it's just you, Raphael...",
  ui_story_5081_50811002_42_dialog_content = "I refuse to go back with someone who enjoys working overtime, so just—",
  ui_story_5081_50811002_43_dialog_content = "What are you talking about, Uriel? I'm here to help everyone out, not because I'm on the clock!",
  ui_story_5081_50811002_44_dialog_content = "To keep you from disturbing the public, I have no choice but to drag you back to Lumopolis! Fun, right?",
  ui_story_5081_50811002_45_dialog_content = "But I'm not done here... I still need to burn down all of Astra...",
  ui_story_5081_50811002_46_dialog_content = "See you later, PlayerName! Oh, and thanks for being so understanding, miss!",
  ui_story_5081_50811002_47_dialog_content = "I know we caused you a lot of trouble, but let me say that you have a really wonderful arcade.",
  ui_story_5081_50811002_48_dialog_content = "Even an Aurorian like Uriel, who thinks everything is meaningless, absolutely loves this place!",
  ui_story_5081_50811002_49_dialog_content = "I'll be sure to come back and play someday too! Bye-bye!",
  ui_story_5081_50811101_1_dialog_content = "... Are they finally gone? Hurry up and lock the door, Sork!",
  ui_story_5081_50811101_2_dialog_content = "I can't believe two famous people showed up back-to-back. Who's next, the City Lord himself?",
  ui_story_5081_50811101_3_dialog_content = "... Probably not.",
  ui_story_5081_50811101_4_dialog_content = "Then maybe Queen Bethlehem? That sounds a little more realistic, right?",
  ui_story_5081_50811101_5_dialog_content = "... I don't think that's the point.",
  ui_story_5081_50811101_6_dialog_content = "I don't care who shows up, as long as it's not Sinsa. If he finds out I got tricked into working here for free...",
  ui_story_5081_50811101_7_dialog_content = "I'll be the laughingstock of the Rediesel Wrench for years to come!",
  ui_story_5081_50811101_8_dialog_content = "Decades, even! Chirp!",
  ui_story_5081_50811101_9_dialog_content = "Give it a rest, you guys! You're scaring Batia!",
  ui_story_5081_50811101_10_dialog_content = "Oh...",
  ui_story_5081_50811101_11_dialog_content = "They thanked me before they left.",
  ui_story_5081_50811101_12_dialog_content = "Huh?",
  ui_story_5081_50811101_13_dialog_content = "Uriel... She came to my arcade on her own accord?",
  ui_story_5081_50811101_14_dialog_content = "Looks like it! I had no idea she went to arcades to blow off steam...",
  ui_story_5081_50811101_15_dialog_content = "That means your store is making a significant contribution in the fight against Eclipsites, Batia!",
  ui_story_5081_50811101_16_dialog_content = "I wouldn't go that far. As for Uriel...",
  ui_story_5081_50811101_17_dialog_content = "If we can meet under normal circumstances, I might be able to recommend a few games just for her.",
  ui_story_5081_50811101_18_dialog_content = "But today... I...",
  ui_story_5081_50811101_19_dialog_content = "What about today?",
  ui_story_5081_50811101_20_dialog_content = "I don't think I've ever seen this many crazy customers in a single day!",
  ui_story_5081_50811101_21_dialog_content = "I knew that this pre-sale was going to get lots of attention from all over Astra...",
  ui_story_5081_50811101_22_dialog_content = "But I never expected to see this many strange and powerful customers! Something's not right about it!",
  ui_story_5081_50811101_23_dialog_content = "So you've finally realized it—but it's too late now!",
  ui_story_5081_50811101_24_dialog_content = "?",
  ui_story_5081_50811101_25_dialog_content = "I allowed the rumors surrounding the legendary \"B\" and her arcade to quickly proliferate through my intelligence network...",
  ui_story_5081_50811101_26_dialog_content = "And now, it's time for me to reap the fruits of my labor.",
  ui_story_5081_50811101_27_dialog_content = "<color=#e8d9bb>Creak—</color>",
  ui_story_5081_50811101_28_dialog_content = "You've all been surrounded, so nobody move.",
  ui_story_5081_50811101_29_dialog_content = "?",
  ui_story_5081_50811101_30_dialog_content = "The truth often lies hidden under layers of darkness, but through my investigation, all will be brought to light.",
  ui_story_5081_50811101_31_dialog_content = "After a lengthy investigation, I have finally uncovered the truth behind this store and its real owner.",
  ui_story_5081_50811101_32_dialog_content = "I have already requested the cooperation of both the Shadowlord and the sheriff of Lumopolis—",
  ui_story_5081_50811101_33_dialog_content = "For the suspected possession of classified information, I hereby declare that the Hidden Fangs must close its doors pending further investigation!",
  ui_story_5081_50811101_34_dialog_content = "Wh-Who do you think you are? What gives you the right to do that?",
  ui_story_5081_50811101_35_dialog_content = "<color=#e8d9bb>Swish—</color>",
  ui_story_5081_50811101_36_dialog_content = "Here is the official warrant, signed by each of the governing bodies involved in the investigation. Need I say more?",
  ui_story_5081_50811101_37_dialog_content = "O-Objection! I never did anything like that at all... I swear...",
  ui_story_5081_50811101_38_dialog_content = "Your objection makes no difference. After all, <color=#FFB400>words</color> mean nothing in this place, do they?",
  ui_story_5081_50811101_39_dialog_content = "Only a challenge will do!",
  ui_story_5081_50811101_40_dialog_content = "Now just hold on a second!",
  ui_story_5081_50811101_41_dialog_content = "I know you have an officially signed warrant, and I know you must've worked really hard on those lines just now...",
  ui_story_5081_50811101_42_dialog_content = "But what the heck are you doing, Intelligence Officer Yin—",
  ui_story_5081_50811101_43_dialog_content = "That's not my name! I am the challenger known as \"Y\"!",
  ui_story_5081_50811101_44_dialog_content = "And I managed to set foot in this arcade just before it closed its doors!",
  ui_story_5081_50811101_45_dialog_content = "The undefeated \"B\" is the master of this place, yes? You wouldn't refuse my challenge, would you?",
  ui_story_5081_50811101_46_dialog_content = "...",
  ui_story_5081_50811101_47_dialog_content = "Don't worry, Batia, I'll go talk to her. This is part of my mission, after all...",
  ui_story_5081_50811101_48_dialog_content = "In fact, I hear the Illumina Federation is prepared to mobilize its entire mainland intelligence network to hunt her down.",
  ui_story_5081_50811101_49_dialog_content = "To be frank, no. In fact, one might say we have a bit of a conflict between us.",
  ui_story_5081_50811101_50_dialog_content = "<size=30>She's been pushing herself so hard lately, perhaps more than necessary.</size>",
  ui_story_5081_50811101_51_dialog_content = "... But not to worry. I will ensure that this matter reaches a satisfactory conclusion.",
  ui_story_5081_50811101_52_dialog_content = "So they were talking about you all this time, Yingel!",
  ui_story_5081_50811101_53_dialog_content = "No wonder Beretta said she saw you outside earlier today... And what's with those sunglasses?",
  ui_story_5081_50811101_54_dialog_content = "That gaze I felt when I first showed up wasn't from Batia... It was you!",
  ui_story_5081_50811101_55_dialog_content = "So... What will they do to Gronru once they find her? They're not gonna punish her, are they?",
  ui_story_5081_50811101_56_dialog_content = "Who knows? After all, this isn't my field of expertise.",
  ui_story_5081_50811101_57_dialog_content = "(... The Illumina Federation sent Yingel, the best of their best soldiers, to hunt down Gronru!)",
  ui_story_5081_50811101_X57_dialog_content = "(Aren't you worried about this? They're not really gonna drag you back by force, are they?!)",
  ui_story_5081_50811101_58_dialog_content = "What's the matter, \"B\"? If it bothers you so much, then just accept my challenge!",
  ui_story_5081_50811101_59_dialog_content = "I accept!",
  ui_story_5081_50811101_60_dialog_content = "As the owner of this arcade, I have to defend it!",
  ui_story_5081_50811101_61_dialog_content = "Wait... Don't tell me you two are gonna—",
  ui_story_5081_50811101_62_dialog_content = "It's time to duel!",
  ui_story_5081_50811102_1_dialog_content = "Is this really all you've got? I expected more from the legendary \"B.\"",
  ui_story_5081_50811102_2_dialog_content = "Your life is like a candle in the wind...",
  ui_story_5081_50811102_3_dialog_content = "Is that what you think?",
  ui_story_5081_50811102_4_dialog_content = "I've been preparing this one-turn kill move just for you! Are you ready for it?",
  ui_story_5081_50811102_5_dialog_content = "What...",
  ui_story_5081_50811102_6_dialog_content = "<color=#e8d9bb>Whoosh, whoosh, whoosh—boom!</color>",
  ui_story_5081_50811102_7_dialog_content = "<size=45>No... Noooo!</size>",
  ui_story_5081_50811102_8_dialog_content = "Yingel's HP went straight to zero...",
  ui_story_5081_50811102_9_dialog_content = "Seriously... I didn't even get to commentate on the match!",
  ui_story_5081_50811102_10_dialog_content = "These two kept explaining their moves every turn, like some lame card game!",
  ui_story_5081_50811102_11_dialog_content = "Heheh, that warrant's probably worthless now!",
  ui_story_5081_50811102_12_dialog_content = "Wait, don't make it sound like we live in a world where winning a game solves everything!",
  ui_story_5081_50811102_13_dialog_content = "How could this be? My strategy was perfect! I've been observing you in this place for so long...",
  ui_story_5081_50811102_14_dialog_content = "Your playstyle, your habits, and even your battles against all of those challengers...",
  ui_story_5081_50811102_15_dialog_content = "No... It's not over yet! I refuse to accept defeat!",
  ui_story_5081_50811102_16_dialog_content = "Best two out of three! This competition's just getting started!",
  ui_story_5081_50811102_17_dialog_content = "Jeez... Yingel's really starting to sound like a cartoon villain now.",
  ui_story_5081_50811102_18_dialog_content = "Fine by me! To protect my arcade, I'll beat you as many times as it takes...",
  ui_story_5081_50811102_19_dialog_content = "This is what PlayerName and the others taught me about being the owner of this place!",
  ui_story_5081_50811102_20_dialog_content = "It's time to duel!",
  ui_story_5081_50811102_21_dialog_content = "Stop it already—",
  ui_story_5081_50811102_22_dialog_content = "Pardon the interruption.",
  ui_story_5081_50811102_23_dialog_content = "Forgive me... for arriving so late.",
  ui_story_5081_50811102_24_dialog_content = "Officer Yingel is already here, I see. Please forgive me for not stopping her sooner as well.",
  ui_story_5081_50811102_25_dialog_content = "That's okay, you came at just the right time! It's not too late to get her to back down!",
  ui_story_5081_50811102_26_dialog_content = "Understood.",
  ui_story_5081_50811102_27_dialog_content = "Officer Yingel, there is more to this mission than we originally thought.",
  ui_story_5081_50811102_28_dialog_content = "Tech Officer Gronru is an important member of our research department... but she is also a very temperamental person.",
  ui_story_5081_50811102_29_dialog_content = "I have already spoken to both Officer Migard and the Committee.",
  ui_story_5081_50811102_30_dialog_content = "Rather than trying to force her to return, it is better for us to continue with our own duties.",
  ui_story_5081_50811102_31_dialog_content = "For the time being, please leave the investigation into Officer Gronru's whereabouts to PlayerName. As for us—",
  ui_story_5081_50811102_32_dialog_content = "Calling for backup already, huh?",
  ui_story_5081_50811102_33_dialog_content = "Just a minor interruption, nothing more. Let's continue.",
  ui_story_5081_50811102_34_dialog_content = "My appeal to reason fell completely on deaf ears!",
  ui_story_5081_50811102_35_dialog_content = "It appears I'll have to update my information regarding Officer Yingel once again...",
  ui_story_5081_50811102_36_dialog_content = "No, Anatoli, you definitely did your best. It's just that she isn't Intelligence Officer Yingel right now—she's the challenger known as \"Y.\"",
  ui_story_5081_50811102_37_dialog_content = "I know what you're really after, \"Y\"! That's why I propose that we work together and complete our mission!",
  ui_story_5081_50811102_38_dialog_content = "!",
  ui_story_5081_50811102_39_dialog_content = "Anatoli already told me. You've been pushing yourself really hard at work, haven't you?",
  ui_story_5081_50811102_40_dialog_content = "When the Illumina Federation leaders assigned you to search for Gronru, it was because they wanted to give you a less stressful assignment.",
  ui_story_5081_50811102_41_dialog_content = "But in the end, they decided to put the job in my hands. If you ask me, they're just complicating things even more!",
  ui_story_5081_50811102_42_dialog_content = "That's why I'd prefer to avoid any more unnecessary conflict and work together with you to finish the mission!",
  ui_story_5081_50811102_43_dialog_content = "...",
  ui_story_5081_50811102_44_dialog_content = "I know you don't want to partner up with anyone, but I bet you don't want Illumina to go without one of their best scientists any longer, right?",
  ui_story_5081_50811102_45_dialog_content = "... And what makes you certain that we'll find the Tech Officer if we work together?",
  ui_story_5081_50811102_46_dialog_content = "All of my intelligence pointed toward her being at this exact location.",
  ui_story_5081_50811102_47_dialog_content = "Yet I saw no sign of her, even after all this time... So I thought that by defeating \"B,\" I could force her to divulge Gronru's whereabouts.",
  ui_story_5081_50811102_48_dialog_content = "Are you capable of beating her, PlayerName? If not, I can only rely on myself...",
  ui_story_5081_50811102_49_dialog_content = "Batia? What do you think of Yingel as a player?",
  ui_story_5081_50811102_50_dialog_content = "You mean her? I find her pretty interesting, honestly. She seems to enjoy games very much too...",
  ui_story_5081_50811102_51_dialog_content = "And she knows how to produce some very high-level strategies, even if she gets carried away with them... I think she's a great player.",
  ui_story_5081_50811102_52_dialog_content = "C-Carried away? Is that your opinion of me?",
  ui_story_5081_50811102_53_dialog_content = "No, that's not right... You're talking about the challenger known as \"Y,\" but...",
  ui_story_5081_50811102_54_dialog_content = "Your opponent is Intelligence Officer Yingel now. Please don't put me on the same level as that last challenger.",
  ui_story_5081_50811102_55_dialog_content = "Now that Batia has acknowledged Yingel's skills, I think it's safe for me to ask now.",
  ui_story_5081_50811102_56_dialog_content = "Gronru's actually hiding somewhere here, isn't she?",
  ui_story_5081_50811102_57_dialog_content = "Oh... I'm so sorry, Gronru...",
  ui_story_5081_50811102_58_dialog_content = "Yes... That's the truth.",
  ui_story_5081_50811102_59_dialog_content = "As long as it's only the two of you...",
  ui_story_5081_50811102_60_dialog_content = "I'm sure she won't mind meeting with you. This way, please.",
  ui_story_5081_50811201_1_dialog_content = "It's a little dark... Please don't fall too far behind.",
  ui_story_5081_50811201_2_dialog_content = "I never expected there to be a tunnel underneath this place.",
  ui_story_5081_50811201_3_dialog_content = "My intelligence reports mentioned nothing about a hidden passage...",
  ui_story_5081_50811201_4_dialog_content = "Gronru went to a lot of trouble to conceal this place. It only makes sense that you didn't know about it...",
  ui_story_5081_50811201_5_dialog_content = "Here we are... Welcome to Gronru's underground studio.",
  ui_story_5081_50811201_6_dialog_content = "It's her private space where she can analyze and restore recently excavated games from ancient civilizations.",
  ui_story_5081_50811201_7_dialog_content = "A video game studio? Does that mean—",
  ui_story_5081_50811201_8_dialog_content = "You were right to assume that Gronru was here all along, PlayerName... but for different reasons.",
  ui_story_5081_50811201_9_dialog_content = "She didn't come here to buy a copy of the fantasy game on pre-sale, because she's the one who restored it in the first place.",
  ui_story_5081_50811201_10_dialog_content = "In other words...",
  ui_story_5081_50811201_11_dialog_content = "She's the real owner of Hidden Fangs, a veteran gamer who supports me in running this arcade.",
  ui_story_5081_50811201_12_dialog_content = "So my intelligence reports were right—this really is her secret base.",
  ui_story_5081_50811201_13_dialog_content = "Shirking her crucial duties as an Illumina officer to fix old video games...",
  ui_story_5081_50811201_14_dialog_content = "I can't think of a more selfish thing to do! Illumina is in the middle of—",
  ui_story_5081_50811201_15_dialog_content = "Middle of what?",
  ui_story_5081_50811201_16_dialog_content = "Give it a rest, Yingel. If PlayerName hadn't gained favor with Batia, it would've taken you another year to find this place!",
  ui_story_5081_50811201_17_dialog_content = "Gained favor with me? He doesn't even come halfway close to doing that...",
  ui_story_5081_50811201_18_dialog_content = "Wait a minute! I'm not an NPC or something... Please don't joke around like that, Gronru!",
  ui_story_5081_50811201_19_dialog_content = "It's just... They seemed to have something really important to tell you, so I brought them here.",
  ui_story_5081_50811201_20_dialog_content = "After all, they're your friends and coworkers...",
  ui_story_5081_50811201_21_dialog_content = "That doesn't mean squat! Didn't I tell you not to let anyone in here until my vacation was over?",
  ui_story_5081_50811201_22_dialog_content = "... B-But you said \"with the exception of especially interesting players\"...",
  ui_story_5081_50811201_23_dialog_content = "\"Especially interesting players\"? You're not talking about PlayerName and Yingel, right?",
  ui_story_5081_50811201_24_dialog_content = "You really think those two stand a chance against the secret mastermind behind the Hidden Fangs?",
  ui_story_5081_50811201_25_dialog_content = "<color=#e8d9bb>Rumble...</color>",
  ui_story_5081_50811201_26_dialog_content = "We're being underestimated, PlayerName.",
  ui_story_5081_50811201_27_dialog_content = "Yeah... But we didn't come here to challenge any \"secret mastermind\" in the first place!",
  ui_story_5081_50811201_28_dialog_content = "That doesn't matter anymore. There's no avoiding this battle now.",
  ui_story_5081_50811201_29_dialog_content = "Tech Officer Gronru, do you have any idea how much chaos your absence has caused back in Illumina?",
  ui_story_5081_50811201_30_dialog_content = "Urgh, what a pain...",
  ui_story_5081_50811201_31_dialog_content = "Don't tell me the latest anti-Eclipsite weaponry started malfunctioning again! If that's the case, then just use something else!",
  ui_story_5081_50811201_32_dialog_content = "My old weapons can do the job just fine!",
  ui_story_5081_50811201_33_dialog_content = "Or has the Committee still not cleaned up after themselves?",
  ui_story_5081_50811201_34_dialog_content = "Always dragging meetings out with their self-important, melodramatic speeches... Does everyone toss their brain out the window when they make it to the top or something?",
  ui_story_5081_50811201_35_dialog_content = "Or maybe some lab folks bicker over which projects to pursue and which ones to scrap again?",
  ui_story_5081_50811201_36_dialog_content = "Any project that fails to pass inspection gets canned without a second thought, even though all they need is a little more support! It pisses me right off!",
  ui_story_5081_50811201_37_dialog_content = "Her mental state...",
  ui_story_5081_50811201_38_dialog_content = "It's even worse than Uriel's, isn't it?",
  ui_story_5081_50811201_39_dialog_content = "Even though you can't bear responsibility for all of those things, that's no excuse for abandoning your post without approval—",
  ui_story_5081_50811201_40_dialog_content = "Who says I didn't get approval? I put in my request for vacation time! And I approved it myself!",
  ui_story_5081_50811201_41_dialog_content = "I even put notices of my time off all over my office! Don't tell me you didn't see them!",
  ui_story_5081_50811201_42_dialog_content = "Urghhhh, that does it! I'm not letting either of you screw up my game of Longzhou Tilemaster—",
  ui_story_5081_50811201_43_dialog_content = "If you want me to go back to the office, you'll have to drag my cold, dead body over there!",
  ui_story_5081_50811201_44_dialog_content = "Longzhou Tilemaster? I think I've heard of that game. It's sort of like mahjong...",
  ui_story_5081_50811201_45_dialog_content = "Huh? But I thought you were finishing up your work on the fantasy game, Gronru? Why did you hit the pause button on that?",
  ui_story_5081_50811201_46_dialog_content = "Hmm... I-It doesn't matter! No one's allowed to disturb me right now, you hear me? No one!",
  ui_story_5081_50811201_47_dialog_content = "Let Gronru's Game begin!",
  ui_story_5081_50811201_48_dialog_content = "... I knew it would end up like this.",
  ui_story_5081_50811201_49_dialog_content = "Get it, Peng-Peng!",
  ui_story_5081_50811201_50_dialog_content = "\"Peng-Peng\"? ... Oh, you mean this little guy.",
  ui_story_5081_50811201_51_dialog_content = "I'm not done yet! Feast your eyes on this: All Green, Four Blessings, and Nine Lotus Lanterns!",
  ui_story_5081_50811201_52_dialog_content = "Hey... Hang on just a second! How am I supposed to keep up with that?",
  ui_story_5081_50811201_53_dialog_content = "I've entered the game! Hang in there, PlayerName!",
  ui_story_5081_50811201_54_dialog_content = "I'm in position as well!",
  ui_story_5081_50811201_55_dialog_content = "Honestly... What kind of person names Eclipsites after a move in mahjong?",
  ui_story_5081_50811201_56_dialog_content = "Who else but the great Gronru, master of all forms of mahjong!",
  ui_story_5081_50811201_57_dialog_content = "All who dare to defy me will be crushed under the colossal weight of my tiles!",
  ui_story_5081_50811201_58_dialog_content = "You came to challenge me, yes? Then bring it on, all three of you! I'll show all of you—",
  ui_story_5081_50811201_59_dialog_content = "That I, Gronkenstein Ruu, am the true and undefeated gamer known as \"B\"!",
  ui_story_5081_50811201_60_dialog_content = "The \"B\" stands for \"boss,\" as in the final boss!",
  ui_story_5081_50811300_1_dialog_content = "<color=#e8d9bb>And so the invincible Gronru is finally defeated.</color>",
  ui_story_5081_50811300_2_dialog_content = "Phew... That was a close one. Gronru almost had us beat.",
  ui_story_5081_50811300_3_dialog_content = "Having a powerful player such as Batia on our team is extremely reassuring.",
  ui_story_5081_50811300_4_dialog_content = "Believe me, everyone played their very best just now. Without you guys... I never could've beaten Gronru...",
  ui_story_5081_50811300_5_dialog_content = "Beaten me? In your dreams! Gronkenstein Ruu can never be defeated!",
  ui_story_5081_50811300_6_dialog_content = "That was only my first form! I still have two forms left, each one twice as strong as the last!",
  ui_story_5081_50811300_7_dialog_content = "Aaaaaahhhh—",
  ui_story_5081_50811300_8_dialog_content = "Wait, Gronru... You're using cheat codes now, aren't you?",
  ui_story_5081_50811300_9_dialog_content = "That's not fair at all!",
  ui_story_5081_50811300_10_dialog_content = "\"Fair\"? That word doesn't exist anywhere in Astra!",
  ui_story_5081_50811300_11_dialog_content = "Cheats are just another part of Gronru's Game! If you don't like it, then get out!",
  ui_story_5081_50811300_12_dialog_content = "Haaaaaahhhh—",
  ui_story_5081_50811300_13_dialog_content = "Wait... Is she really just using cheats?",
  ui_story_5081_50811300_14_dialog_content = "Why is the whole room shaking like it's about to self-destruct?",
  ui_story_5081_50811300_15_dialog_content = "Is she overloading the game machine by using too many cheats?",
  ui_story_5081_50811300_16_dialog_content = "Every piece of equipment in this room is interconnected...",
  ui_story_5081_50811300_17_dialog_content = "G-Gronru! If this keeps up, the whole arcade will explode!",
  ui_story_5081_50811300_18_dialog_content = "Then let it explode... I'd rather that happen instead of losing to you and having to go back to work!",
  ui_story_5081_50811300_19_dialog_content = "Why should I deal with all the aftermath when none of it was my fault?",
  ui_story_5081_50811300_20_dialog_content = "To hell with their unfair rules! They're just making more work for me to cover up their own screw-ups!",
  ui_story_5081_50811300_21_dialog_content = "Those high-and-mighty fools could never understand! The only reason we work is to properly enjoy playing games in our off-time!",
  ui_story_5081_50811300_22_dialog_content = "An Astra where I can't play games to my heart's content... is destined to disappear, along with my third form—",
  ui_story_5081_50811300_23_dialog_content = "<color=#e8d9bb>Beep—</color>",
  ui_story_5081_50811300_24_dialog_content = "?",
  ui_story_5081_50811300_25_dialog_content = "The shaking stopped?",
  ui_story_5081_50811300_26_dialog_content = "Yeah. We needed to snap her out of it, so I shut off the power to her machines.",
  ui_story_5081_50811300_27_dialog_content = "You don't blame me, do you Gronru? Besides, you always turn on auto-save for your games...",
  ui_story_5081_50811300_28_dialog_content = "I don't care about my save data anymore! I won't go back, not even if I'm dead!",
  ui_story_5081_50811300_29_dialog_content = "You're so pathetic without your cheats, Gronru.",
  ui_story_5081_50811300_30_dialog_content = "That's rich coming from you, Yingel! Didn't you just get carried by Batia? Even without cheats, you'd never stand a chance against me one-on-one!",
  ui_story_5081_50811300_31_dialog_content = "Maybe so, but I still won... We all did!",
  ui_story_5081_50811300_32_dialog_content = "Nasty... Curse you!",
  ui_story_5081_50811300_33_dialog_content = "Stop it, both of you! I didn't bring them to challenge you, Gronru! It's just...",
  ui_story_5081_50811300_34_dialog_content = "I noticed you weren't doing so well lately... but I didn't know how to help you...",
  ui_story_5081_50811300_35_dialog_content = "After all... I have no idea what your leaders think.",
  ui_story_5081_50811300_36_dialog_content = "But I think it's fine if you don't like them, Gronru!",
  ui_story_5081_50811300_37_dialog_content = "That's why... I wanted to bring you some of the people you might like!",
  ui_story_5081_50811300_38_dialog_content = "Me?",
  ui_story_5081_50811300_39_dialog_content = "Her?",
  ui_story_5081_50811300_40_dialog_content = "D-Don't look at me!",
  ui_story_5081_50811300_41_dialog_content = "That's right! After playing with them and against them, I can tell that they have a true passion for video games!",
  ui_story_5081_50811300_42_dialog_content = "And unlike me... they don't hole themselves up in their rooms every day. They're your colleagues, as well as your friends.",
  ui_story_5081_50811300_43_dialog_content = "That's why I think they're better at understanding your problems than I am.",
  ui_story_5081_50811300_44_dialog_content = "Batia...",
  ui_story_5081_50811300_45_dialog_content = "So, could you please just think of this as me putting together an impromptu gaming convention at Hidden Fangs?",
  ui_story_5081_50811300_46_dialog_content = "I hope this gives you a chance to share your troubles with us... so we can find a way forward together!",
  ui_story_5081_50811300_47_dialog_content = "*sniffs*",
  ui_story_5081_50811300_48_dialog_content = "Waaaaaaaaah—",
  ui_story_5081_50811300_49_dialog_content = "I can't stand those obnoxious meetings or the mountains of reports I always have to write!",
  ui_story_5081_50811300_50_dialog_content = "There's never enough time to play games, much less restore them... That's why I decided to hide out over here!",
  ui_story_5081_50811300_51_dialog_content = "I meant to finish my work on that fantasy game as soon as possible, but I was in such a bad mood that I couldn't make any progress...",
  ui_story_5081_50811300_52_dialog_content = "So I thought, \"Maybe a game of Longzhou Tilemaster will help me unwind a little...\"",
  ui_story_5081_50811300_53_dialog_content = "But once I started playing, I couldn't put the controller down!",
  ui_story_5081_50811300_54_dialog_content = "I told myself I'd stop after reaching the eighth rank, but then I kept going until the ninth rank, and then the tenth...",
  ui_story_5081_50811300_55_dialog_content = "I was having terrible luck the whole time, so it took forever to make any progress... And now the fantasy game's release is just around the corner...",
  ui_story_5081_50811300_56_dialog_content = "There's no way I'm gonna make it in time now!",
  ui_story_5081_50811300_57_dialog_content = "My work's still not done! The game's still not done! I haven't gotten a single thing done!",
  ui_story_5081_50811300_58_dialog_content = "*sobbing* Why does life have to be such a grind? I don't wanna play anymore—",
  ui_story_5081_50811300_59_dialog_content = "PlayerName! You gotta help me delete myself from the world!",
  ui_story_5081_50811300_60_dialog_content = "H-Hey! Don't say scary stuff like that!",
  ui_story_5081_50811300_61_dialog_content = "This world needs you, Gronru! Besides, life's never been a single-player game...",
  ui_story_5081_50811300_62_dialog_content = "Why not let us play with you?",
  ui_story_5081_50811300_63_dialog_content = "If we face this stage called life together, I'm sure we can clear it with flying colors! It'd be much more fun than going it alone, at least!",
  ui_story_5081_50811300_64_dialog_content = "As for the redundant, unnecessary, stressful torture in Illumina...",
  ui_story_5081_50811300_65_dialog_content = "... I mean, as for your work, I'm sure Anatoli and I can help you streamline some of those processes.",
  ui_story_5081_50811300_66_dialog_content = "And when it comes to restoring video games, Odi definitely knows her stuff!",
  ui_story_5081_50811300_67_dialog_content = "Maybe No. 33 can help out too!",
  ui_story_5081_50811300_68_dialog_content = "As for me... I'm not good at anything besides video games, but you can always ask me to be your tester!",
  ui_story_5081_50811300_69_dialog_content = "You're not just good at video games, Batia.",
  ui_story_5081_50811300_70_dialog_content = "We're all gamers here, but you have something special that no one else has...",
  ui_story_5081_50811300_71_dialog_content = "That's the Hidden Fangs, the ultimate destination for gamers worldwide! Not to mention your reputation as the legendary gamer \"B\"!",
  ui_story_5081_50811300_72_dialog_content = "Just think of all the challengers you defeated to protect your arcade today!",
  ui_story_5081_50811300_73_dialog_content = "I...",
  ui_story_5081_50811300_74_dialog_content = "Batia... Oh, Batiaaaa—",
  ui_story_5081_50811300_75_dialog_content = "I-It's gonna be okay, Gronru! Don't cry...",
  ui_story_5081_50811300_76_dialog_content = "You're all grown up now! You've gone from a quiet little girl to a dependable arcade manager!",
  ui_story_5081_50811300_77_dialog_content = "PlayerName's speeches are as effective as ever, it seems...",
  ui_story_5081_50811300_78_dialog_content = "L-Like I said, I'm not an NPC!",
  ui_story_5081_50811300_79_dialog_content = "But you really are amazing! You dealt with so many problems all by yourself!",
  ui_story_5081_50811300_80_dialog_content = "You even handled someone as infuriating as Yingel!",
  ui_story_5081_50811300_81_dialog_content = "?",
  ui_story_5081_50811300_82_dialog_content = "I think I'll have to challenge you again just to show you how <color=#FFB400>infuriating</color> I can really be, Tech Officer Gronru.",
  ui_story_5081_50811300_83_dialog_content = "Oh, so you wanna keep playing?",
  ui_story_5081_50811300_84_dialog_content = "Not at all. I'm just issuing a challenge.",
  ui_story_5081_50811300_85_dialog_content = "Heheheh, it looks like video games really can make anything happen... I feel so much better after everything that's happened today!",
  ui_story_5081_50811300_86_dialog_content = "Do you guys still want to challenge me? I'm up for it, but I just need some time first.",
  ui_story_5081_50811300_87_dialog_content = "I want to go finish my work on that fantasy game right now! After that, you can all be my valuable testers for my latest work!",
  ui_story_5081_50811300_88_dialog_content = "This is your one and only chance to challenge the real final boss!",
  ui_story_5081_50811300_89_dialog_content = "Because after I go back to Illumina, this achievement won't be available in the official version!",
  ui_story_5081_50811300_90_dialog_content = "We'll see if you have what it takes to unlock it in the first place!",
  ui_story_5081_50811300_91_dialog_content = "So it's settled then? You're finally going to return to Illumina?",
  ui_story_5081_50811300_92_dialog_content = "... Humph!",
  ui_story_5081_50811300_93_dialog_content = "Huh? Where are you going, Yingel?",
  ui_story_5081_50811300_94_dialog_content = "Do you really need to ask? I'm going to get some last-minute training in before she finishes restoring the game.",
  ui_story_5081_50811300_95_dialog_content = "I won't stop until I beat her so badly that she decides to give up games and go back to work for good.",
  ui_story_5081_50811300_96_dialog_content = "Oh... G-Good luck with that...",
  ui_story_5081_50811300_97_dialog_content = "What about you, Batia?",
  ui_story_5081_50811300_98_dialog_content = "If it's alright with you, I'd like to pick out a few of these games to play with you, PlayerName.",
  ui_story_5081_50811300_99_dialog_content = "Oh, okay! These are from your roost, right?",
  ui_story_5081_50811300_100_dialog_content = "Let's see... White Night Album 2, huh? Why don't we play this one?",
  ui_story_5081_50811300_101_dialog_content = "Um... Okay.",
  ui_story_5081_50811300_102_dialog_content = "Something tells me you're gonna be really good at this game. Let's see what choices you make...",
  ui_story_5081_50811300_103_dialog_content = "Sure! Let's boot it up!",
  ui_story_5081_50811300_104_dialog_content = "Is this really the time to be relaxing like this? We're challenging Gronru again soon, remember?",
  ui_story_5081_50811300_105_dialog_content = "We're just playing video games, Yingel! Besides, who says this game is gonna be easy? Come see for yourself!",
  ui_story_5081_50811300_106_dialog_content = "<color=#e8d9bb>And so, while Gronru puts the finishing touches on her newest game, the rest of us also sit around her and play games...</color>",
  ui_story_5081_50811300_107_dialog_content = "<color=#e8d9bb>Together, we have a night of simple, pure enjoyment in each other's company.</color>",
  ui_story_5081_50811300_108_dialog_content = "The wait is finally over, everyone! May I present to you—the fantasy game that's gonna make all of Astra go nuts!",
  ui_story_5081_50811300_109_dialog_content = "As its first three players, I hope you're all ready!",
  ui_story_5081_50811300_110_dialog_content = "My sniper rifle's tired of waiting.",
  ui_story_5081_50811300_111_dialog_content = "Heh, then it looks like I can set it to the hardest possible difficulty!",
  ui_story_5081_50811300_112_dialog_content = "What about you two?",
  ui_story_5081_50811300_113_dialog_content = "I'm ready!",
  ui_story_5081_50811300_114_dialog_content = "I'll do my best too!",
  ui_story_5081_50811300_115_dialog_content = "Good, then let the countdown begin! Three! Two! One!",
  ui_story_5081_50811300_116_dialog_content = "Game start!"
}
return config
